/**
 * Word·PowerPoint 단축키 85개의 한 줄 설명 — 열 언어.
 *
 * 키 이름과 기능 이름은 어느 언어 안에서도 라틴 글자 그대로 둔다. Ctrl은 어디서나
 * Ctrl이고 Track Changes는 어디서나 Track Changes다. 옮기는 것은 "무엇을 하는가"와
 * "무엇을 하나 틀리기 쉬운가" 한 문장뿐이다 — desc-office.ts가 표에서 그렇게 했다.
 *
 * 이 두 앱에서 사람이 걸려 넘어지는 자리는 셋이다. 하나는 맥에서 Ctrl 조합이
 * Cmd로 바뀌지 않고 그대로 남는 곳(Ctrl+H, Ctrl+Space), 둘은 발표 중에만 듣는
 * 키(B·W·Ctrl+L), 셋은 초점이 글이냐 표냐 개체냐로 같은 키가 다른 일을 하는
 * 곳이다. 설명 한 문장은 되도록 그 자리를 가리킨다.
 *
 * 열 칸을 배열로 적는다 — 순서는 ko·en·es·pt·ja·de·fr·hi·zh·tw.
 */
import type { Ten } from './types.ts';

export const SC_DESC_OFFICE2: Record<string, Ten> = {
  /* ═════════ word ═════════ */

  /* ───────── Styles ───────── */
  'word-heading-1': ["문단을 Heading 1 스타일로 만들어 문서의 뼈대에 넣습니다. 탐색 창과 목차는 글자 크기가 아니라 스타일을 읽으니, 굵게 크게만 해 둔 제목은 어느 쪽에도 잡히지 않습니다.", "Puts the paragraph into the document outline as Heading 1; the Navigation pane and the table of contents read the style, so a line you merely made big and bold is invisible to both.", "Convierte el párrafo en Heading 1 y lo mete en el esquema del documento; el panel de navegación y el índice leen el estilo, así que una línea solo puesta en negrita y grande no aparece en ninguno.", "Transforma o parágrafo em Heading 1 e o coloca na estrutura do documento; o painel de navegação e o sumário leem o estilo, então uma linha apenas em negrito e maior não aparece em nenhum dos dois.", "段落を Heading 1 の見出しにして文書の骨組みに入れます。ナビゲーション ウィンドウと目次は文字の大きさではなくスタイルを見るので、太字で大きくしただけの行はどちらにも出てきません。", "Macht den Absatz zur Überschrift Heading 1 und nimmt ihn in die Dokumentstruktur auf; Navigationsbereich und Inhaltsverzeichnis lesen die Formatvorlage, eine nur fett und groß gesetzte Zeile erscheint in keinem von beiden.", "Fait du paragraphe un titre Heading 1 et l’inscrit dans le plan du document ; le volet de navigation et la table des matières lisent le style, donc une ligne seulement mise en gras et en grand n’apparaît nulle part.", "पैराग्राफ़ को Heading 1 बनाकर दस्तावेज़ की रूपरेखा में जोड़ता है; Navigation pane और विषय-सूची शैली पढ़ते हैं, इसलिए सिर्फ़ बड़ा और bold किया गया शीर्षक दोनों में नहीं दिखता।", "把这一段设为 Heading 1，纳入文档大纲；导航窗格和目录看的是样式而不是字号，所以只调大加粗的标题两边都收不到。", "把這一段設為 Heading 1，納入文件大綱；導覽窗格和目錄看的是樣式而不是字級，所以只調大加粗的標題兩邊都收不到。"],
  'word-heading-2': ["한 단 아래 제목을 만듭니다. 위에 Heading 1이 없으면 목차에서 계층이 어긋나 보이니, 문서 처음부터 차례로 매기는 것이 안전합니다.", "Applies the next level down; with no Heading 1 above it the outline nests oddly, so it is safest to work down the levels in order from the top of the document.", "Aplica el nivel siguiente; si arriba no hay un Heading 1, el esquema se anida de forma extraña, así que conviene ir bajando de nivel en orden desde el principio.", "Aplica o nível seguinte; sem um Heading 1 acima, a estrutura fica aninhada de forma estranha, então é mais seguro descer os níveis em ordem desde o começo.", "一段下の見出しにします。上に Heading 1 が無いと目次の階層がずれて見えるので、文書の頭から順に段を下げるのが安全です。", "Vergibt die nächste Ebene; fehlt darüber ein Heading 1, verschachtelt sich die Gliederung schief — sicherer ist es, die Ebenen vom Dokumentanfang an der Reihe nach zu vergeben.", "Applique le niveau juste en dessous ; sans Heading 1 au-dessus, le plan s’imbrique de travers, mieux vaut donc descendre les niveaux dans l’ordre depuis le début.", "एक स्तर नीचे का शीर्षक लगाता है; ऊपर Heading 1 न हो तो रूपरेखा का क्रम बिगड़ जाता है, इसलिए दस्तावेज़ के आरंभ से क्रम में स्तर घटाना सुरक्षित है।", "套用下一级标题；上面没有 Heading 1 时大纲的层级会错位，所以从文档开头按顺序往下分级最稳。", "套用下一級標題；上面沒有 Heading 1 時大綱的層級會錯位，所以從文件開頭按順序往下分級最穩。"],
  'word-heading-3': ["세 번째 단 제목입니다. 기본 조합은 세 단까지만 있어서 Heading 4 아래는 스타일 갤러리나 Styles 창에서 골라야 합니다.", "The third outline level; Word ships bindings for three levels only, so Heading 4 and below have to be picked from the style gallery or the Styles pane.", "El tercer nivel del esquema; Word solo trae combinaciones para tres niveles, de modo que Heading 4 y siguientes se eligen en la galería de estilos o en el panel Styles.", "O terceiro nível da estrutura; o Word traz combinações só para três níveis, então Heading 4 e os seguintes saem da galeria de estilos ou do painel Styles.", "三段目の見出しです。既定の組み合わせは三段までしかないので、Heading 4 以下はスタイル ギャラリーか Styles ウィンドウから選びます。", "Die dritte Gliederungsebene; Word bringt Kürzel nur für drei Ebenen mit, Heading 4 und tiefer wählt man in der Formatvorlagengalerie oder im Bereich Styles.", "Le troisième niveau du plan ; Word ne fournit des raccourcis que pour trois niveaux, Heading 4 et suivants se prennent dans la galerie de styles ou le volet Styles.", "तीसरे स्तर का शीर्षक; Word में केवल तीन स्तरों के लिए संयोजन हैं, इसलिए Heading 4 और नीचे style gallery या Styles pane से चुनने पड़ते हैं।", "第三级标题；Word 只为三级标题配了组合键，Heading 4 以下要在样式库或 Styles 窗格里挑。", "第三級標題；Word 只為三級標題配了組合鍵，Heading 4 以下要在樣式庫或 Styles 窗格裡挑。"],
  'word-normal-style': ["문단을 기본 Normal 스타일로 되돌립니다. 스타일만 바뀌므로 손으로 준 굵게나 색은 그대로 남고, 그것까지 벗기려면 서식 지우기를 따로 눌러야 합니다.", "Sends the paragraph back to the Normal style; only the style changes, so bold or colour you applied by hand survives and needs clearing separately.", "Devuelve el párrafo al estilo Normal; solo cambia el estilo, así que la negrita o el color que pusiste a mano sobreviven y hay que quitarlos aparte.", "Devolve o parágrafo ao estilo Normal; só o estilo muda, então negrito ou cor aplicados à mão continuam e precisam ser limpos à parte.", "段落を既定の Normal スタイルに戻します。変わるのはスタイルだけなので、手で付けた太字や色は残り、それは別に書式の解除が必要です。", "Setzt den Absatz auf die Formatvorlage Normal zurück; nur die Vorlage wechselt, per Hand gesetztes Fett oder Farbe bleibt und muss extra entfernt werden.", "Ramène le paragraphe au style Normal ; seul le style change, le gras ou la couleur posés à la main restent et doivent être effacés séparément.", "पैराग्राफ़ को Normal शैली पर लौटाता है; बदलती केवल शैली है, इसलिए हाथ से लगाया bold या रंग बचा रहता है और उसे अलग से हटाना पड़ता है।", "把这一段还原成 Normal 样式；变的只是样式，你手动加的加粗和颜色还在，得另外清一遍。", "把這一段還原成 Normal 樣式；變的只是樣式，你手動加的粗體和顏色還在，得另外清一遍。"],
  'word-apply-styles': ["스타일 이름을 직접 쳐서 적용하는 작은 상자를 엽니다. Word for Mac에는 이 상자가 따로 없고 사이드바의 Styles 창이 그 몫까지 하기 때문에 기본 조합이 없습니다.", "Opens the small box where you type a style name; Word for Mac has no separate Apply Styles box — its sidebar Styles pane does both jobs — so no binding exists there.", "Abre la cajita en la que escribes el nombre de un estilo; Word for Mac no tiene esa caja aparte, su panel Styles de la barra lateral hace las dos cosas, así que allí no hay combinación.", "Abre a caixinha onde você digita o nome de um estilo; o Word for Mac não tem essa caixa separada, o painel Styles da barra lateral faz os dois papéis, então lá não há combinação.", "スタイル名を打って適用する小さな入力箱を開きます。Word for Mac にはこの箱が別に無く、サイドバーの Styles ウィンドウが兼ねているため、既定の組み合わせがありません。", "Öffnet das kleine Feld, in das man einen Formatvorlagennamen tippt; Word for Mac hat kein eigenes Apply-Styles-Feld — dort übernimmt der Styles-Bereich beides — und kennt deshalb kein Kürzel.", "Ouvre la petite zone où l’on tape un nom de style ; Word for Mac n’a pas cette zone distincte, son volet Styles fait les deux, et n’a donc aucun raccourci.", "वह छोटा बॉक्स खोलता है जिसमें शैली का नाम टाइप करते हैं; Word for Mac में यह बॉक्स अलग से नहीं है, वहाँ sidebar का Styles pane दोनों काम करता है, इसलिए कोई संयोजन नहीं है।", "打开可以直接键入样式名的小框；Word for Mac 没有单独的 Apply Styles 框，侧边栏的 Styles 窗格一并承担，所以那边没有组合键。", "開啟可以直接輸入樣式名稱的小框；Word for Mac 沒有單獨的 Apply Styles 框，側邊欄的 Styles 窗格一併承擔，所以那邊沒有組合鍵。"],
  'word-styles-pane': ["문서에 쓰인 스타일을 모두 늘어놓는 Styles 창을 엽니다. 맥 Word는 이 창을 Toolbox 안에 두고 기본 조합을 주지 않아서, 필요하면 Tools의 키보드 사용자 지정에서 손수 붙여야 합니다.", "Opens the Styles pane listing every style in the document; Word for Mac keeps that pane in its Toolbox with no default binding, so you have to assign one under Tools and Customize Keyboard.", "Abre el panel Styles con todos los estilos del documento; Word for Mac guarda ese panel en el Toolbox sin combinación por omisión, así que hay que asignarla en Tools y Customize Keyboard.", "Abre o painel Styles com todos os estilos do documento; o Word for Mac guarda esse painel no Toolbox sem combinação padrão, então é preciso atribuir uma em Tools e Customize Keyboard.", "文書で使われているスタイルを並べる Styles ウィンドウを開きます。Mac の Word はこれを Toolbox に置き既定の割り当てが無いので、Tools のキーボードのカスタマイズで自分で付けます。", "Öffnet den Styles-Bereich mit allen Formatvorlagen des Dokuments; Word for Mac führt ihn in der Toolbox ohne Standardkürzel — man legt es unter Tools und Customize Keyboard selbst an.", "Ouvre le volet Styles qui liste tous les styles du document ; Word for Mac le place dans sa Toolbox sans raccourci par défaut, à créer soi-même via Tools puis Customize Keyboard.", "दस्तावेज़ की सारी शैलियाँ दिखाने वाला Styles pane खोलता है; Mac का Word इसे Toolbox में रखता है और कोई डिफ़ॉल्ट संयोजन नहीं देता, इसलिए Tools में Customize Keyboard से ख़ुद जोड़ना पड़ता है।", "打开列出文档中所有样式的 Styles 窗格；Mac 版 Word 把它放在 Toolbox 里且没有默认组合键，要在 Tools 的自定义键盘里自己指定。", "開啟列出文件中所有樣式的 Styles 窗格；Mac 版 Word 把它放在 Toolbox 裡且沒有預設組合鍵，要在 Tools 的自訂鍵盤裡自己指定。"],

  /* ───────── Search ───────── */
  'word-find': ["문서에서 글자를 찾습니다. 윈도우에서는 대화상자가 아니라 왼쪽 탐색 창이 열려 결과가 목록으로 쌓이고, 그 창의 제목 탭으로 문서를 건너다닐 수 있습니다.", "Searches the document; on Windows it opens the Navigation pane on the left rather than a dialog, listing every hit, and its Headings tab doubles as a way to jump around.", "Busca en el documento; en Windows abre el panel de navegación de la izquierda en vez de un cuadro de diálogo, apila los resultados y su pestaña de títulos sirve además para saltar por el texto.", "Procura no documento; no Windows abre o painel de navegação à esquerda em vez de uma caixa de diálogo, lista todas as ocorrências e a aba de títulos serve para pular pelo texto.", "文書の中から文字を探します。Windows ではダイアログではなく左のナビゲーション ウィンドウが開いて結果が一覧になり、その見出しタブで文書を行き来できます。", "Sucht im Dokument; unter Windows öffnet sich links der Navigationsbereich statt eines Dialogs, listet alle Treffer und dient über die Registerkarte Überschriften auch zum Springen.", "Recherche dans le document ; sous Windows, c’est le volet de navigation à gauche qui s’ouvre, pas une boîte de dialogue, avec la liste des occurrences et un onglet de titres pour naviguer.", "दस्तावेज़ में लिखा खोजता है; Windows पर संवाद-बक्सा नहीं, बाईं ओर का Navigation pane खुलता है, सभी मेल सूची में आते हैं और उसका Headings टैब आने-जाने का रास्ता भी है।", "在文档里查找；Windows 上打开的是左侧导航窗格而不是对话框，命中结果列成一排，它的标题选项卡还能用来跳转。", "在文件裡尋找；Windows 上開啟的是左側導覽窗格而不是對話框，命中結果列成一排，它的標題頁籤還能用來跳轉。"],
  'word-replace': ["찾기와 바꾸기 창을 바꾸기 탭으로 엽니다. 맥에서도 Cmd가 아니라 Ctrl 그대로인데, Cmd+H는 macOS가 앱 감추기로 이미 가져갔기 때문입니다.", "Opens Find and Replace on the Replace tab; on the Mac it stays on Ctrl instead of moving to Cmd, because macOS already spends Cmd+H on hiding the app.", "Abre Buscar y reemplazar en la pestaña de reemplazo; en Mac se queda en Ctrl y no pasa a Cmd, porque macOS ya usa Cmd+H para ocultar la aplicación.", "Abre Localizar e substituir na aba de substituição; no Mac continua com Ctrl em vez de Cmd, porque o macOS já usa Cmd+H para esconder o aplicativo.", "検索と置換を置換タブで開きます。Mac でも Cmd ではなく Ctrl のままです — Cmd+H は macOS がアプリを隠す操作に取っているからです。", "Öffnet Suchen und Ersetzen auf der Registerkarte Ersetzen; am Mac bleibt es bei Ctrl statt Cmd, weil macOS Cmd+H schon zum Ausblenden der App verbraucht.", "Ouvre Rechercher et remplacer sur l’onglet de remplacement ; sur Mac il reste en Ctrl au lieu de passer à Cmd, car macOS consacre déjà Cmd+H au masquage de l’application.", "Find and Replace को Replace टैब पर खोलता है; Mac पर भी यह Cmd नहीं, Ctrl ही रहता है, क्योंकि Cmd+H को macOS ऐप छिपाने के लिए ले चुका है।", "打开查找和替换并停在替换页；Mac 上它仍是 Ctrl 而不是换成 Cmd，因为 Cmd+H 已经被 macOS 用来隐藏应用了。", "開啟尋找及取代並停在取代頁；Mac 上它仍是 Ctrl 而不是換成 Cmd，因為 Cmd+H 已經被 macOS 用來隱藏應用程式了。"],
  'word-go-to': ["쪽 번호나 책갈피, 표를 적어 그 자리로 곧장 넘어갑니다. 맥은 Cmd+G가 이미 다음 찾기라서 Option을 하나 더 붙입니다.", "Jumps straight to a page number, a bookmark or a table you name; the Mac adds Option because Cmd+G there already means find next.", "Salta directamente a un número de página, un marcador o una tabla que indiques; en Mac se añade Option porque Cmd+G ya significa buscar siguiente.", "Salta direto para um número de página, um marcador ou uma tabela que você indicar; no Mac entra o Option porque Cmd+G já é localizar próxima.", "ページ番号やブックマーク、表を指定してその場所へ直接飛びます。Mac では Cmd+G が既に次を検索なので、Option が一つ加わります。", "Springt direkt zu einer Seitenzahl, einer Textmarke oder einer Tabelle; am Mac kommt Option hinzu, weil Cmd+G dort schon Weitersuchen bedeutet.", "Saute directement à un numéro de page, un signet ou un tableau indiqué ; sur Mac on ajoute Option car Cmd+G y signifie déjà rechercher le suivant.", "पृष्ठ संख्या, bookmark या किसी तालिका का नाम देकर सीधे वहाँ पहुँचता है; Mac पर Option जुड़ता है क्योंकि वहाँ Cmd+G का अर्थ पहले से अगला खोजो है।", "输入页码、书签或表格名就直接跳过去；Mac 上多加一个 Option，因为 Cmd+G 在那里已经是查找下一个。", "輸入頁碼、書籤或表格名稱就直接跳過去；Mac 上多加一個 Option，因為 Cmd+G 在那裡已經是尋找下一個。"],

  /* ───────── Review ───────── */
  'word-track-changes': ["Track Changes 기록을 켜고 끕니다. 끄는 것은 기록을 멈추는 것일 뿐이라 이미 남은 수정 표시는 그대로 있고, 표시가 안 보이는 것은 검토 표시 방식이 따로 정해져 있기 때문입니다.", "Turns Track Changes recording on and off; switching it off only stops recording, so marks already in the file stay, and marks you cannot see are hidden by the Display for Review setting instead.", "Activa y desactiva el registro de Track Changes; apagarlo solo detiene el registro, las marcas ya guardadas siguen ahí, y si no las ves es por la opción de visualización para revisión.", "Liga e desliga o registro do Track Changes; desligar só para de registrar, as marcas já existentes ficam, e se você não as vê a culpa é da opção de exibição para revisão.", "Track Changes の記録を切り替えます。切っても記録が止まるだけで、既に付いた変更の印は残ります。印が見えないのは表示の設定が別にあるからです。", "Schaltet die Aufzeichnung von Track Changes ein und aus; das Ausschalten stoppt nur die Aufzeichnung, vorhandene Markierungen bleiben, und unsichtbare Markierungen versteckt die Anzeigeeinstellung.", "Active et désactive l’enregistrement de Track Changes ; le couper arrête seulement l’enregistrement, les marques déjà présentes restent, et si elles sont invisibles c’est le mode d’affichage des révisions qui les masque.", "Track Changes का रिकॉर्ड करना चालू-बंद करता है; बंद करने से केवल रिकॉर्डिंग रुकती है, पहले के निशान बने रहते हैं, और निशान न दिखें तो वह Display for Review की सेटिंग है।", "开关 Track Changes 的记录；关掉只是停止记录，已经留下的修订标记还在，看不见标记是显示以供审阅那个设置在挡着。", "開關 Track Changes 的記錄；關掉只是停止記錄，已經留下的修訂標記還在，看不見標記是顯示以供審閱那個設定在擋著。"],
  'word-insert-comment': ["고른 자리에 메모를 붙입니다. 맥은 Windows의 M이 아니라 A를 쓰는 드문 자리이고, 아무것도 고르지 않으면 커서가 놓인 낱말에 붙습니다.", "Attaches a comment to the selection; unusually the Mac uses A where Windows uses M, and with nothing selected it anchors to the word under the cursor.", "Añade un comentario a lo seleccionado; curiosamente Mac usa A donde Windows usa M, y sin selección se ancla a la palabra bajo el cursor.", "Anexa um comentário à seleção; curiosamente o Mac usa A onde o Windows usa M, e sem seleção ele se ancora na palavra sob o cursor.", "選んだ場所にコメントを付けます。Mac は Windows の M ではなく A を使う珍しい割り当てで、何も選んでいなければカーソルの下の語に付きます。", "Hängt einen Kommentar an die Auswahl; ungewöhnlich nutzt der Mac A, wo Windows M nimmt, und ohne Auswahl verankert er am Wort unter dem Cursor.", "Attache un commentaire à la sélection ; fait rare, le Mac utilise A là où Windows utilise M, et sans sélection l’ancre se pose sur le mot sous le curseur.", "चुने हुए हिस्से पर टिप्पणी जोड़ता है; ख़ास बात यह है कि Windows के M की जगह Mac पर A है, और कुछ चुना न हो तो cursor वाले शब्द से जुड़ जाता है।", "给选中的内容加批注；少见地，Windows 用 M，Mac 却用 A，什么都没选时会锚在光标所在的词上。", "給選取的內容加註解；少見地，Windows 用 M，Mac 卻用 A，什麼都沒選時會錨在游標所在的字詞上。"],

  /* ───────── Breaks ───────── */
  'word-page-break': ["여기서 쪽을 끊고 다음 쪽 첫 줄로 넘깁니다. 위쪽 글이 늘거나 줄어도 이 끊김은 그 자리에 남고, 머리글이나 쪽 번호를 갈라 매기려면 필요한 구역 나누기에는 아예 기본 조합이 없습니다.", "Breaks the page here and pushes the text to the top of the next one; the break stays put as the text above grows, and the section break you need for separate headers or page numbering has no default binding at all.", "Corta la página aquí y empuja el texto al principio de la siguiente; el salto se queda donde está aunque crezca el texto de arriba, y el salto de sección que hace falta para encabezados o numeración aparte no tiene combinación alguna.", "Quebra a página aqui e joga o texto para o topo da seguinte; a quebra fica onde está mesmo se o texto acima crescer, e a quebra de seção necessária para cabeçalhos ou numeração separados não tem combinação nenhuma.", "ここでページを切って次のページの先頭へ送ります。上の文が増えてもこの区切りはその場に残り、ヘッダーやページ番号を分けるのに必要なセクション区切りには既定の組み合わせがありません。", "Bricht die Seite hier um und schiebt den Text an den Anfang der nächsten; der Umbruch bleibt stehen, auch wenn der Text darüber wächst — für den Abschnittswechsel, den getrennte Kopfzeilen oder Seitenzahlen brauchen, gibt es gar kein Kürzel.", "Coupe la page ici et pousse le texte en haut de la suivante ; le saut reste en place même si le texte au-dessus s’allonge, et le saut de section nécessaire à des en-têtes ou une numérotation distincts n’a aucun raccourci.", "यहीं पृष्ठ तोड़कर आगे का लेख अगले पृष्ठ के ऊपर भेज देता है; ऊपर का लेख बढ़े तो भी यह विराम वहीं रहता है, और अलग header या पृष्ठ-संख्या के लिए ज़रूरी section break का कोई डिफ़ॉल्ट संयोजन ही नहीं है।", "在这里断页，把后面的字推到下一页开头；上面的内容增减，这个断点也留在原处，而要分开页眉或页码所需的分节符根本没有默认组合键。", "在這裡斷頁，把後面的字推到下一頁開頭；上面的內容增減，這個斷點也留在原處，而要分開頁首或頁碼所需的分節符根本沒有預設組合鍵。"],
  'word-column-break': ["단을 끊어 다음 단 위로 넘깁니다. 단이 하나뿐인 문서에서는 쪽 넘김처럼 보이는데, 그래서 구역을 나눈 줄로 잘못 아는 사람이 많습니다.", "Ends the column and moves the text to the top of the next one; in a single-column document that looks just like a page break, which is why people think they inserted a section break.", "Termina la columna y lleva el texto al principio de la siguiente; en un documento de una sola columna parece un salto de página, y por eso muchos creen que insertaron un salto de sección.", "Encerra a coluna e leva o texto para o topo da próxima; num documento de uma coluna isso parece uma quebra de página, e por isso muita gente pensa que inseriu uma quebra de seção.", "段を切って次の段の先頭へ送ります。段が一つだけの文書ではページ区切りと同じに見えるため、セクションを分けたと勘違いされがちです。", "Beendet die Spalte und setzt den Text an den Anfang der nächsten; in einem einspaltigen Dokument sieht das wie ein Seitenumbruch aus, weshalb viele einen Abschnittswechsel darin sehen.", "Termine la colonne et porte le texte en haut de la suivante ; dans un document à une seule colonne cela ressemble à un saut de page, d’où la confusion avec un saut de section.", "स्तंभ ख़त्म करके लेख अगले स्तंभ के ऊपर ले जाता है; एक ही स्तंभ वाले दस्तावेज़ में यह पृष्ठ-विराम जैसा लगता है, इसीलिए लोग इसे section break समझ लेते हैं।", "结束当前分栏，把字送到下一栏顶端；单栏文档里它看着就像分页符，所以很多人以为自己插了分节符。", "結束目前分欄，把字送到下一欄頂端；單欄文件裡它看著就像分頁符，所以很多人以為自己插了分節符。"],

  /* ───────── Paragraph ───────── */
  'word-single-spacing': ["줄 간격을 한 줄로 맞춥니다. 낱말 하나만 골라도 문단 전체에 걸리고, 문단 앞뒤 여백은 따로 있는 값이라 여전히 넓어 보일 수 있습니다.", "Sets the line spacing to single; it applies to the whole paragraph even if you selected one word, and the space before and after the paragraph is a separate setting that can still look wide.", "Pone el interlineado en sencillo; afecta a todo el párrafo aunque solo hayas seleccionado una palabra, y el espacio anterior y posterior es otro ajuste que puede seguir pareciendo amplio.", "Deixa o espaçamento entre linhas simples; vale para o parágrafo inteiro mesmo que você tenha selecionado uma palavra, e o espaço antes e depois é outro ajuste que ainda pode parecer largo.", "行間を一行に合わせます。語を一つ選んだだけでも段落全体に効き、段落の前後の間隔は別の設定なので広く見えることがあります。", "Stellt den Zeilenabstand auf einfach; er gilt für den ganzen Absatz, auch wenn nur ein Wort markiert war, und der Abstand vor und nach dem Absatz ist eine eigene Einstellung, die weiterhin luftig wirkt.", "Met l’interligne à simple ; il s’applique à tout le paragraphe même si un seul mot était sélectionné, et l’espace avant et après est un réglage distinct qui peut rester large.", "पंक्ति-अंतर को एक पंक्ति कर देता है; एक शब्द चुना हो तो भी पूरे पैराग्राफ़ पर लगता है, और पैराग्राफ़ के आगे-पीछे का अंतर अलग सेटिंग है जो फिर भी चौड़ा दिख सकता है।", "把行距设为单倍；哪怕只选了一个词也作用于整段，而段前段后的间距是另一项设置，看着可能还是很松。", "把行距設為單行；哪怕只選了一個字也作用於整段，而段前段後的間距是另一項設定，看著可能還是很鬆。"],
  'word-one-and-half-spacing': ["줄 간격을 1.5줄로 둡니다. 제출용 문서에서 가장 많이 요구되는 값이고, 여기서 값을 바꾸면 문단 스타일이 아니라 그 문단에만 직접 서식으로 들어갑니다.", "Sets 1.5-line spacing, the value most often demanded for submitted work; applied this way it becomes direct formatting on that paragraph rather than part of the style.", "Aplica un interlineado de 1,5 líneas, el valor que más piden en trabajos entregados; hecho así queda como formato directo del párrafo y no dentro del estilo.", "Aplica espaçamento de 1,5 linha, o valor mais pedido em trabalhos entregues; feito assim, vira formatação direta daquele parágrafo e não parte do estilo.", "行間を 1.5 行にします。提出物で最も求められる値ですが、こうして当てると段落スタイルではなくその段落だけの直接書式になります。", "Setzt den Zeilenabstand auf 1,5 Zeilen, den bei Abgaben am häufigsten verlangten Wert; so gesetzt wird er direkte Formatierung dieses Absatzes, nicht Teil der Formatvorlage.", "Applique un interligne de 1,5 ligne, la valeur la plus exigée pour les travaux rendus ; posée ainsi, elle devient une mise en forme directe du paragraphe et non du style.", "पंक्ति-अंतर 1.5 पंक्ति कर देता है, जमा किए जाने वाले काम में सबसे ज़्यादा माँगा जाने वाला मान; इस तरह लगाने पर यह शैली का हिस्सा नहीं, उसी पैराग्राफ़ की सीधी formatting बनता है।", "把行距设为 1.5 倍，交作业最常被要求的值；这样加上去属于该段的直接格式，而不是写进样式里。", "把行距設為 1.5 倍，交作業最常被要求的值；這樣加上去屬於該段的直接格式，而不是寫進樣式裡。"],
  'word-double-spacing': ["줄 간격을 두 줄로 둡니다. 문단 뒤 여백까지 남아 있으면 요구된 것보다 더 벌어져 보이니, 두 값을 함께 봐야 합니다.", "Sets double line spacing; if space after the paragraph is still switched on the result looks wider than what was asked for, so check both values together.", "Pone interlineado doble; si sigue activo el espacio posterior al párrafo, el resultado se ve más suelto de lo pedido, así que revisa ambos valores juntos.", "Deixa o espaçamento duplo; se o espaço depois do parágrafo continuar ligado, o resultado fica mais largo do que o pedido, então olhe os dois valores juntos.", "行間を二行にします。段落後の間隔が残っていると求められた以上に開いて見えるので、二つの値を合わせて確かめます。", "Setzt doppelten Zeilenabstand; ist der Abstand nach dem Absatz noch aktiv, wirkt das Ergebnis weiter als verlangt — beide Werte zusammen prüfen.", "Met un interligne double ; si l’espace après le paragraphe est encore actif, le rendu paraît plus aéré que demandé : vérifiez les deux valeurs ensemble.", "पंक्ति-अंतर दुगना कर देता है; पैराग्राफ़ के बाद का अंतर चालू रह जाए तो नतीजा माँगे से ज़्यादा खुला लगता है, इसलिए दोनों मान साथ देखें।", "把行距设为双倍；若段后间距还开着，效果会比要求的更松，两个值要一起看。", "把行距設為兩倍；若段後間距還開著，效果會比要求的更鬆，兩個值要一起看。"],
  'word-align-left': ["문단을 왼쪽에 맞춥니다. 표 안에서는 그 칸의 글에만 걸리고, 칸 자체의 가로 맞춤은 표 도구에 따로 있습니다.", "Aligns the paragraph left; inside a table it moves only the text in that cell, while the cell's own alignment lives in the table tools.", "Alinea el párrafo a la izquierda; dentro de una tabla solo mueve el texto de esa celda, la alineación de la celda está en las herramientas de tabla.", "Alinha o parágrafo à esquerda; dentro de uma tabela move apenas o texto daquela célula, a alinhamento da própria célula fica nas ferramentas de tabela.", "段落を左に寄せます。表の中ではそのセルの文字だけに効き、セル自体の配置は表のツールに別にあります。", "Richtet den Absatz links aus; in einer Tabelle betrifft es nur den Text dieser Zelle, die Ausrichtung der Zelle selbst steckt in den Tabellentools.", "Aligne le paragraphe à gauche ; dans un tableau, cela ne déplace que le texte de la cellule, l’alignement de la cellule est dans les outils de tableau.", "पैराग्राफ़ को बाएँ किनारे लगाता है; तालिका के भीतर यह केवल उस cell के लेख पर लगता है, cell का अपना संरेखण table tools में है।", "把段落靠左对齐；在表格里它只动那一格里的文字，单元格本身的对齐在表格工具里。", "把段落靠左對齊；在表格裡它只動那一格裡的文字，儲存格本身的對齊在表格工具裡。"],
  'word-align-center': ["문단을 가운데로 모읍니다. 제목을 가운데로 두려고 앞에 빈칸을 넣는 것과 달리, 여백이 바뀌어도 가운데가 유지됩니다.", "Centres the paragraph; unlike padding a title with spaces, it stays centred when the margins change.", "Centra el párrafo; a diferencia de rellenar un título con espacios, sigue centrado cuando cambian los márgenes.", "Centraliza o parágrafo; diferente de empurrar um título com espaços, ele continua centralizado quando as margens mudam.", "段落を中央に寄せます。空白を入れて見出しを真ん中に見せる方法と違い、余白が変わっても中央のままです。", "Zentriert den Absatz; anders als ein mit Leerzeichen verschobener Titel bleibt er zentriert, wenn sich die Ränder ändern.", "Centre le paragraphe ; contrairement à un titre calé avec des espaces, il reste centré quand les marges changent.", "पैराग्राफ़ को बीच में ले आता है; रिक्त स्थान भरकर शीर्षक बीच में दिखाने के उलट, हाशिये बदलने पर भी यह बीच में रहता है।", "把段落居中；和用空格把标题顶到中间不同，页边距变了它还是居中。", "把段落置中；和用空格把標題頂到中間不同，頁面邊界變了它還是置中。"],
  'word-align-right': ["문단을 오른쪽에 맞춥니다. 날짜나 서명 줄에 쓰는데, 탭으로 밀어 둔 줄에 이것을 걸면 탭이 남아 이상하게 벌어집니다.", "Aligns the paragraph right, the usual choice for a date or a signature line; applied to a line you had pushed with tabs, the leftover tabs open odd gaps.", "Alinea el párrafo a la derecha, lo habitual para una fecha o una firma; si la línea ya estaba empujada con tabuladores, esos tabuladores dejan huecos raros.", "Alinha o parágrafo à direita, o normal para data ou linha de assinatura; se a linha já foi empurrada com tabulações, elas deixam vãos estranhos.", "段落を右に寄せます。日付や署名の行に使いますが、タブで押していた行に当てるとタブが残って妙な隙間が空きます。", "Richtet den Absatz rechts aus, üblich für Datum oder Signaturzeile; auf einer mit Tabulatoren geschobenen Zeile bleiben die Tabulatoren und reißen seltsame Lücken.", "Aligne le paragraphe à droite, l’usage pour une date ou une signature ; sur une ligne déjà poussée par des tabulations, celles-ci laissent des trous étranges.", "पैराग्राफ़ को दाएँ किनारे लगाता है, तारीख़ या हस्ताक्षर की पंक्ति के लिए यही चलन है; जो पंक्ति tab से खिसकाई गई थी, उसमें बचे tab अजीब खाली जगह छोड़ देते हैं।", "把段落靠右对齐，日期和签名行常用；若这行原先是用制表符顶过去的，留下的制表符会撑出奇怪的空隙。", "把段落靠右對齊，日期和簽名行常用；若這行原先是用定位字元頂過去的，留下的定位字元會撐出奇怪的空隙。"],
  'word-justify': ["양쪽 끝을 가지런히 맞춥니다. 낱말 사이를 늘려 맞추기 때문에 긴 낱말이 섞이면 빈칸이 강처럼 흐르고, 문단 마지막 줄은 늘어나지 않습니다.", "Stretches the lines to both margins; it pads the gaps between words, so long words open rivers of white space, and the last line of the paragraph is left alone.", "Estira las líneas hasta ambos márgenes; ensancha los huecos entre palabras, así que las palabras largas abren ríos de blanco, y la última línea del párrafo no se estira.", "Estica as linhas até as duas margens; ele alarga os vãos entre palavras, então palavras longas abrem rios de branco, e a última linha do parágrafo fica intacta.", "行を左右の端に揃えます。語の間を伸ばして揃えるので、長い語が混じると空白が川のように流れ、段落の最後の行は伸びません。", "Zieht die Zeilen an beide Ränder; gestreckt werden die Wortabstände, weshalb lange Wörter weiße Flüsse aufreißen und die letzte Absatzzeile unangetastet bleibt.", "Étire les lignes jusqu’aux deux marges ; ce sont les espaces entre les mots qui s’élargissent, d’où des rivières blanches avec les mots longs, et la dernière ligne du paragraphe reste intacte.", "पंक्तियों को दोनों हाशियों तक तान देता है; शब्दों के बीच की जगह खींचकर, इसलिए लंबे शब्दों से सफ़ेद नदियाँ बन जाती हैं और पैराग्राफ़ की अंतिम पंक्ति नहीं तनती।", "把每行拉到左右两端；靠撑开词间空隙来对齐，所以长词一多就会拉出一条条白河，而段落最后一行不参与拉伸。", "把每行拉到左右兩端；靠撐開字詞間的空隙來對齊，所以長字一多就會拉出一條條白河，而段落最後一行不參與拉伸。"],
  'word-hanging-indent': ["첫 줄만 남기고 아래 줄을 들여씁니다. 참고문헌 목록이 이 모양이고, 누를 때마다 들여쓰기가 탭 한 칸씩 더 깊어집니다.", "Indents every line but the first, the shape a bibliography entry needs; each press moves the indent one tab stop deeper.", "Sangra todas las líneas menos la primera, la forma que necesita una entrada bibliográfica; cada pulsación mueve la sangría un tabulador más.", "Recua todas as linhas menos a primeira, o formato que uma referência bibliográfica pede; cada toque empurra o recuo mais uma tabulação.", "一行目を残して以下の行を字下げします。参考文献の並びがこの形で、押すたびに字下げがタブ一つ分深くなります。", "Rückt alle Zeilen außer der ersten ein — die Form, die ein Literaturverzeichnis braucht; jeder Druck schiebt den Einzug einen Tabstopp weiter.", "Indente toutes les lignes sauf la première, la forme exigée par une notice bibliographique ; chaque pression décale le retrait d’un taquet.", "पहली पंक्ति छोड़कर बाक़ी पंक्तियाँ अंदर कर देता है, संदर्भ-सूची का यही रूप होता है; हर बार दबाने पर indent एक tab और गहरा हो जाता है।", "首行不动，其余各行缩进，参考文献条目就是这个样子；每按一次缩进再深一个制表位。", "首行不動，其餘各行縮排，參考書目條目就是這個樣子；每按一次縮排再深一個定位點。"],
  'word-remove-hanging-indent': ["내어쓰기를 한 칸 되돌립니다. 여러 번 눌러 깊어진 들여쓰기는 그만큼 되돌려야 하고, 문단 자체의 왼쪽 여백은 남습니다.", "Steps the hanging indent back one stop; an indent you pushed several times has to be pulled back the same number of times, and the paragraph's own left indent stays.", "Retrocede un paso la sangría francesa; una sangría empujada varias veces hay que devolverla otras tantas, y la sangría izquierda del párrafo se queda.", "Volta um passo do recuo deslocado; um recuo empurrado várias vezes precisa voltar o mesmo número de vezes, e o recuo esquerdo do parágrafo permanece.", "ぶら下げ字下げを一つ戻します。何度も押して深くした分は同じ回数戻す必要があり、段落自体の左の字下げは残ります。", "Nimmt den hängenden Einzug eine Stufe zurück; mehrfach geschoben, muss er ebenso oft zurückgeholt werden, und der linke Absatzeinzug bleibt.", "Ramène le retrait négatif d’un cran ; poussé plusieurs fois, il doit être ramené autant de fois, et le retrait gauche du paragraphe subsiste.", "hanging indent को एक पायदान पीछे करता है; कई बार बढ़ाया indent उतनी ही बार घटाना पड़ता है, और पैराग्राफ़ का बायाँ indent बना रहता है।", "把悬挂缩进退回一格；按了几次就要退几次，段落本身的左缩进还留着。", "把凸出縮排退回一格；按了幾次就要退幾次，段落本身的左縮排還留著。"],
  'word-change-case': ["고른 글의 대소문자를 문장·소문자·대문자로 돌려 가며 바꿉니다. 글자 자체가 바뀌는 것이라 서식으로 크게 보이게 하는 것과 달리 되돌리려면 한 바퀴 더 돌려야 합니다.", "Cycles the selection through sentence case, lower case and upper case; it rewrites the letters themselves, unlike the all-capitals format, so undoing it means cycling round again.", "Recorre la selección por tipo frase, minúsculas y mayúsculas; reescribe las letras, a diferencia del formato de mayúsculas, así que para volver hay que dar otra vuelta.", "Percorre a seleção entre frase, minúsculas e maiúsculas; reescreve as próprias letras, ao contrário do formato de maiúsculas, então voltar exige dar outra volta.", "選んだ文字を文頭・小文字・大文字と順に切り替えます。書式で大きく見せるのと違い文字そのものが変わるので、戻すにはもう一周回します。", "Schaltet die Auswahl zwischen Satz-, Klein- und Großschreibung um; die Buchstaben selbst werden umgeschrieben, anders als beim Großbuchstaben-Format, weshalb Rückgängigmachen eine weitere Runde braucht.", "Fait défiler la sélection entre minuscule initiale, minuscules et majuscules ; ce sont les lettres qui changent, contrairement au format majuscules, donc revenir demande un tour de plus.", "चयन को वाक्य-रूप, छोटे और बड़े अक्षरों के बीच घुमाता है; यह अक्षर ही बदल देता है, all-capitals formatting की तरह नहीं, इसलिए वापस लाने के लिए एक चक्कर और लगाना पड़ता है।", "让选中的文字在句首大写、全小写、全大写之间轮换；它改的是字母本身，不像全大写格式那样只是外观，要退回就得再转一圈。", "讓選取的文字在句首大寫、全小寫、全大寫之間輪換；它改的是字母本身，不像全大寫格式那樣只是外觀，要退回就得再轉一圈。"],

  /* ───────── Formatting ───────── */
  'word-copy-formatting': ["고른 글의 서식을 마우스 없이 집어 옵니다. Microsoft가 이 조합을 예전 Ctrl+Shift+C 자리에서 옮겼기 때문에, 오래 쓴 손과 옛 빌드에서는 다른 조합이 듣습니다.", "Picks up the formatting of the selection without touching the Format Painter button; Microsoft moved this off the old Ctrl+Shift+C, so long-standing habits and older builds answer to the other pair.", "Toma el formato de lo seleccionado sin tocar el botón de copiar formato; Microsoft cambió esta combinación desde el antiguo Ctrl+Shift+C, así que las costumbres viejas y las versiones antiguas responden al otro par.", "Pega a formatação da seleção sem tocar no botão do pincel de formatação; a Microsoft tirou isso do antigo Ctrl+Shift+C, então hábitos antigos e versões velhas respondem ao outro par.", "選んだ文字の書式をマウスに触らずに拾います。Microsoft がこの割り当てを昔の Ctrl+Shift+C から移したので、長年の手癖や古いビルドでは別の組み合わせが効きます。", "Nimmt die Formatierung der Auswahl auf, ohne den Format-Übertragen-Pinsel anzuklicken; Microsoft hat das vom alten Ctrl+Shift+C weggezogen, weshalb alte Gewohnheiten und ältere Builds auf das andere Paar hören.", "Prélève la mise en forme de la sélection sans passer par le pinceau ; Microsoft a déplacé ce raccourci depuis l’ancien Ctrl+Shift+C, si bien que les vieilles habitudes et les anciennes versions répondent à l’autre paire.", "चुने हुए हिस्से की formatting माउस के बिना उठा लेता है; Microsoft ने इसे पुराने Ctrl+Shift+C से हटा दिया, इसलिए पुरानी आदत और पुराने builds दूसरी जोड़ी पर काम करते हैं।", "不碰格式刷按钮就把选中内容的格式取过来；Microsoft 把这个组合从旧的 Ctrl+Shift+C 挪走了，所以老习惯和旧版本认的是另一对。", "不碰複製格式按鈕就把選取內容的格式取過來；Microsoft 把這個組合從舊的 Ctrl+Shift+C 挪走了，所以老習慣和舊版本認的是另一對。"],
  'word-paste-formatting': ["집어 온 서식을 지금 고른 글에 입힙니다. 글자는 그대로 두고 서식만 바꾸며, 한 번 집으면 여러 곳에 이어서 입힐 수 있습니다.", "Applies the formatting you picked up to the current selection; the words stay, only their formatting changes, and one pick-up can be pasted onto several places in a row.", "Aplica el formato tomado a lo seleccionado ahora; las palabras se quedan y solo cambia su formato, y una sola toma se puede pegar en varios sitios seguidos.", "Aplica a formatação capturada à seleção atual; as palavras ficam, só a formatação muda, e uma captura serve para vários trechos em sequência.", "拾った書式を今選んでいる文字に当てます。文字はそのままで書式だけ変わり、一度拾えば続けて何か所にも当てられます。", "Überträgt die aufgenommene Formatierung auf die aktuelle Auswahl; die Wörter bleiben, nur ihre Formatierung wechselt, und eine Aufnahme lässt sich hintereinander auf mehrere Stellen anwenden.", "Applique la mise en forme prélevée à la sélection courante ; les mots restent, seule leur mise en forme change, et un seul prélèvement se colle sur plusieurs endroits de suite.", "उठाई गई formatting को अब चुने हिस्से पर लगाता है; शब्द वही रहते हैं, केवल उनकी formatting बदलती है, और एक बार उठाकर कई जगह लगातार लगा सकते हैं।", "把取来的格式贴到当前选中的内容上；字不动，只换格式，取一次可以连着贴到好几处。", "把取來的格式貼到目前選取的內容上；字不動，只換格式，取一次可以連著貼到好幾處。"],
  'word-clear-formatting': ["손으로 준 글자 서식을 벗겨 스타일이 정한 모습으로 되돌립니다. 맥에서도 Cmd가 아니라 Ctrl 그대로인데, macOS에서 그 조합은 입력기 전환이기도 해서 먹히지 않는 일이 있습니다.", "Strips the character formatting you applied by hand and leaves what the style defines; it stays on Ctrl on the Mac, where the same combination also switches input sources and can swallow the keystroke.", "Quita el formato de carácter que pusiste a mano y deja lo que define el estilo; en Mac se queda en Ctrl, donde esa misma combinación cambia el método de entrada y puede tragarse la pulsación.", "Retira a formatação de caractere aplicada à mão e deixa o que o estilo define; no Mac continua com Ctrl, onde a mesma combinação também troca o método de entrada e pode engolir a tecla.", "手で付けた文字書式をはがし、スタイルが定める姿に戻します。Mac でも Cmd ではなく Ctrl のままで、macOS ではこの組み合わせが入力ソースの切り替えでもあるため効かないことがあります。", "Entfernt die von Hand gesetzte Zeichenformatierung und lässt stehen, was die Formatvorlage vorgibt; am Mac bleibt es bei Ctrl, wo dieselbe Kombination auch die Eingabequelle wechselt und den Anschlag verschluckt.", "Retire la mise en forme de caractère posée à la main et laisse ce que définit le style ; sur Mac il reste en Ctrl, où la même combinaison change aussi de source de saisie et peut avaler la frappe.", "हाथ से लगाई गई character formatting हटाकर शैली का तय रूप छोड़ देता है; Mac पर भी यह Ctrl ही रहता है, और वहाँ यही संयोजन input source भी बदलता है, इसलिए कभी दबाव निगल लिया जाता है।", "剥掉你手动加的字符格式，只留样式规定的样子；Mac 上它仍是 Ctrl，而同一个组合在 macOS 还是切换输入法，按键可能被吃掉。", "剝掉你手動加的字元格式，只留樣式規定的樣子；Mac 上它仍是 Ctrl，而同一個組合在 macOS 還是切換輸入法，按鍵可能被吃掉。"],
  'word-superscript': ["글자를 위로 올려 작게 씁니다. 켠 채로 계속 치면 뒤에 오는 글자도 올라가므로, 각주 번호 하나만 올렸으면 다시 눌러 끕니다.", "Raises the text into superscript; it stays on as you keep typing, so press it again once the raised character is done.", "Sube el texto a superíndice; sigue activo mientras escribes, así que púlsalo de nuevo cuando termines el carácter elevado.", "Eleva o texto para sobrescrito; continua ativo enquanto você digita, então aperte de novo quando terminar o caractere elevado.", "文字を上に上げて小さく書きます。付けたまま打ち続けると後の文字も上がるので、上げ終えたらもう一度押して切ります。", "Hebt den Text in Hochstellung; sie bleibt beim Weitertippen aktiv, also nach dem hochgestellten Zeichen erneut drücken.", "Passe le texte en exposant ; l’état reste actif pendant la saisie, alors appuyez de nouveau une fois le caractère surélevé écrit.", "लेख को ऊपर उठाकर superscript कर देता है; टाइप करते रहने पर चालू रहता है, इसलिए ऊपर वाला अक्षर लिख चुकें तो फिर दबाकर बंद करें।", "把文字提成上标；开着的时候后面接着打的字也会上去，写完那个上标就再按一次关掉。", "把文字提成上標；開著的時候後面接著打的字也會上去，寫完那個上標就再按一次關掉。"],
  'word-subscript': ["글자를 아래로 내려 작게 씁니다. 화학식이나 아래 첨자에 쓰고, 위로 올리기와 함께 켜지지는 않습니다.", "Drops the text into subscript, the way a chemical formula wants it; it cannot be on at the same time as superscript.", "Baja el texto a subíndice, como lo pide una fórmula química; no puede estar activo a la vez que el superíndice.", "Rebaixa o texto para subscrito, como uma fórmula química pede; não pode ficar ativo junto com o sobrescrito.", "文字を下に下げて小さく書きます。化学式などに使い、上付きと同時には付きません。", "Setzt den Text tief, wie es eine chemische Formel braucht; gleichzeitig mit Hochstellung geht es nicht.", "Passe le texte en indice, comme l’exige une formule chimique ; il ne peut pas être actif en même temps que l’exposant.", "लेख को नीचे लाकर subscript कर देता है, जैसा रासायनिक सूत्र चाहता है; यह superscript के साथ एक ही समय चालू नहीं रह सकता।", "把文字降成下标，化学式就要这个；它不能和上标同时开着。", "把文字降成下標，化學式就要這個；它不能和上標同時開著。"],
  'word-strikethrough': ["글에 가로줄을 긋습니다. 맥에만 조합이 있고 Word for Windows는 이 기능에 기본 조합을 주지 않아, 윈도우에서는 Home 탭의 글꼴 그룹에서 누르거나 직접 조합을 만들어야 합니다.", "Draws a line through the text; only the Mac has a binding, because Word for Windows ships none — there you click it in the Font group on the Home tab or assign a combination yourself.", "Traza una línea sobre el texto; solo Mac tiene combinación, porque Word for Windows no trae ninguna: allí se pulsa en el grupo Font de la pestaña Home o se asigna una a mano.", "Risca o texto; só o Mac tem combinação, porque o Word for Windows não traz nenhuma: lá você clica no grupo Font da guia Home ou define uma você mesmo.", "文字に横線を引きます。組み合わせがあるのは Mac だけで、Word for Windows は既定を用意していないため、Home タブのフォントの組で押すか自分で割り当てます。", "Zieht eine Linie durch den Text; nur der Mac hat ein Kürzel, denn Word for Windows liefert keines — dort klickt man es in der Gruppe Font auf der Registerkarte Home oder legt selbst eines fest.", "Barre le texte ; seul le Mac a un raccourci, car Word for Windows n’en fournit aucun — il faut y cliquer dans le groupe Font de l’onglet Home ou en attribuer un soi-même.", "लेख पर आड़ी रेखा खींचता है; संयोजन केवल Mac पर है, क्योंकि Word for Windows कोई डिफ़ॉल्ट नहीं देता — वहाँ Home टैब के Font समूह में क्लिक करें या ख़ुद संयोजन बनाएँ।", "给文字划一道横线；只有 Mac 有组合键，Word for Windows 根本没给默认组合，那边要点 Home 选项卡的字体组或自己指定一个。", "給文字劃一道橫線；只有 Mac 有組合鍵，Word for Windows 根本沒給預設組合，那邊要按 Home 索引標籤的字型群組或自己指定一個。"],
  'word-small-caps': ["소문자를 작은 대문자 모양으로 보이게 합니다. 글자는 그대로 소문자라서, 서식 없는 곳에 붙이면 원래 소문자로 돌아갑니다.", "Shows lower-case letters as small capitals; the letters underneath are still lower case, so pasting them somewhere unformatted brings the small letters back.", "Muestra las minúsculas como versalitas; las letras siguen siendo minúsculas, así que al pegarlas en un sitio sin formato vuelven a ser pequeñas.", "Mostra as minúsculas como versaletes; as letras continuam minúsculas, então colar em um lugar sem formatação traz as pequenas de volta.", "小文字を小さな大文字の見た目にします。文字そのものは小文字のままなので、書式のない場所へ貼ると元の小文字に戻ります。", "Zeigt Kleinbuchstaben als Kapitälchen; die Buchstaben selbst bleiben klein, beim Einfügen an eine unformatierte Stelle kehren sie zurück.", "Affiche les minuscules en petites capitales ; les lettres restent des minuscules, donc un collage dans un endroit sans mise en forme les fait réapparaître.", "छोटे अक्षरों को छोटे बड़े अक्षरों जैसा दिखाता है; अक्षर असल में छोटे ही रहते हैं, इसलिए बिना formatting वाली जगह चिपकाने पर वे छोटे ही लौट आते हैं।", "让小写字母显示成小型大写；底下的字母仍是小写，粘到没有格式的地方就又变回小写。", "讓小寫字母顯示成小型大寫；底下的字母仍是小寫，貼到沒有格式的地方就又變回小寫。"],
  'word-all-caps': ["고른 글을 모두 대문자로 보이게 합니다. 이것도 서식이라 실제 글자는 그대로여서, 소문자로 찾아도 여전히 걸립니다.", "Displays the selection in capitals; this is formatting rather than a rewrite, so a search for the lower-case word still finds it.", "Muestra la selección en mayúsculas; es formato y no una reescritura, así que buscar la palabra en minúsculas sigue encontrándola.", "Exibe a seleção em maiúsculas; é formatação e não reescrita, então buscar a palavra em minúsculas continua achando.", "選んだ文字を大文字の見た目にします。これも書式で実際の文字は変わらないため、小文字で検索しても見つかります。", "Zeigt die Auswahl in Großbuchstaben; es ist Formatierung, kein Umschreiben, deshalb findet eine Suche nach dem kleingeschriebenen Wort sie weiterhin.", "Affiche la sélection en majuscules ; c’est une mise en forme et non une réécriture, donc une recherche du mot en minuscules le trouve toujours.", "चयन को बड़े अक्षरों में दिखाता है; यह formatting है, अक्षर बदलते नहीं, इसलिए छोटे अक्षरों से खोजने पर भी मिल जाता है।", "把选中内容显示成全大写；这只是格式而不是改写，所以用小写去搜依然搜得到。", "把選取內容顯示成全大寫；這只是格式而不是改寫，所以用小寫去搜依然搜得到。"],
  'word-underline-words': ["낱말에만 밑줄을 긋고 낱말 사이 빈칸은 건너뜁니다. 서식이 빈칸까지 이어지지 않아서 표 제목 줄이 깔끔하게 보입니다.", "Underlines the words but skips the spaces between them, which keeps a heading line from looking like one long rule.", "Subraya las palabras pero salta los espacios entre ellas, de modo que una línea de encabezado no parece una raya continua.", "Sublinha as palavras mas pula os espaços entre elas, o que evita que uma linha de título pareça um traço contínuo.", "語だけに下線を引き、語の間の空白は飛ばします。空白まで線が続かないので、見出しの行がすっきり見えます。", "Unterstreicht die Wörter, überspringt aber die Leerzeichen dazwischen, sodass eine Überschriftszeile nicht wie ein durchgehender Strich aussieht.", "Souligne les mots mais saute les espaces entre eux, ce qui évite qu’une ligne de titre ressemble à un long trait.", "केवल शब्दों को रेखांकित करता है और बीच के रिक्त स्थान छोड़ देता है, जिससे शीर्षक की पंक्ति एक लंबी लकीर जैसी नहीं लगती।", "只给词加下划线，跳过词与词之间的空格，标题行就不会看着像一整条横线。", "只給字詞加底線，跳過字詞之間的空格，標題行就不會看著像一整條橫線。"],
  'word-double-underline': ["밑줄을 두 줄로 긋습니다. 회계 문서에서 합계 줄에 쓰는 모양이고, 보통 밑줄과 서로 바꿔 켜집니다.", "Underlines with two lines, the accounting convention for a total row; it and the plain underline replace each other rather than stacking.", "Subraya con dos líneas, la convención contable para la fila de totales; se sustituye con el subrayado normal en vez de acumularse.", "Sublinha com duas linhas, a convenção contábil para a linha de total; ele e o sublinhado simples se substituem em vez de somar.", "下線を二本引きます。会計書類の合計行に使う形で、普通の下線とは重ならず入れ替わります。", "Unterstreicht doppelt, wie es die Buchhaltung für die Summenzeile verlangt; einfache und doppelte Unterstreichung ersetzen sich gegenseitig.", "Souligne d’un double trait, la convention comptable pour la ligne de total ; il remplace le soulignement simple au lieu de s’y ajouter.", "दो रेखाओं से रेखांकित करता है, लेखा दस्तावेज़ों में योग की पंक्ति के लिए यही चलन है; यह साधारण रेखांकन के साथ जुड़ता नहीं, उसकी जगह ले लेता है।", "画双下划线，会计文件里的合计行就是这么标；它和普通下划线是互相替换，不会叠在一起。", "畫雙底線，會計文件裡的合計列就是這麼標；它和普通底線是互相替換，不會疊在一起。"],

  /* ───────── Characters ───────── */
  'word-nonbreaking-space': ["두 낱말을 한 줄에 붙여 둡니다. 숫자와 단위, 이름과 이름 사이가 줄 끝에서 갈라지는 것을 막는 데 쓰고, 서식 기호를 켜면 보통 빈칸과 달리 동그란 표시로 보입니다.", "Keeps two words on the same line — the fix for a number torn from its unit, or a name split at the line end; with formatting marks on it shows as a small circle instead of a dot.", "Mantiene dos palabras en la misma línea: el remedio para un número separado de su unidad o un nombre partido al final del renglón; con las marcas de formato se ve como un circulito en vez de un punto.", "Mantém duas palavras na mesma linha: a solução para um número separado da unidade ou um nome partido no fim da linha; com as marcas de formatação aparece como um círculo em vez de um ponto.", "二つの語を同じ行に留めます。数値と単位、姓と名が行末で切れるのを防ぐもので、編集記号を表示すると普通の空白と違って丸い印で見えます。", "Hält zwei Wörter in derselben Zeile — das Mittel gegen eine Zahl, die von ihrer Einheit getrennt wird, oder einen am Zeilenende zerrissenen Namen; bei eingeschalteten Steuerzeichen erscheint ein kleiner Kreis statt eines Punkts.", "Garde deux mots sur la même ligne : le remède au nombre séparé de son unité ou au nom coupé en fin de ligne ; avec les marques de mise en forme, il s’affiche en petit cercle et non en point.", "दो शब्दों को एक ही पंक्ति में बाँधे रखता है — संख्या और इकाई या नाम पंक्ति के अंत में टूटने से बचते हैं; formatting marks चालू हों तो यह बिंदु की जगह छोटे गोले जैसा दिखता है।", "把两个词锁在同一行——数字和单位、姓和名在行尾被拆开时就用它；打开格式标记后，它显示成小圆圈而不是点。", "把兩個字詞鎖在同一行——數字和單位、姓和名在行尾被拆開時就用它；打開格式標記後，它顯示成小圓圈而不是點。"],
  'word-nonbreaking-hyphen': ["붙임표에서 줄이 갈리지 않게 합니다. 전화번호나 제품 번호가 줄 끝에서 반으로 쪼개지는 것을 막고, 보통 붙임표와 글자는 같아 보여도 다른 문자입니다.", "Stops a line from breaking at a hyphen, so a phone number or a part number is not split in half at the margin; it looks like a normal hyphen but is a different character.", "Evita que la línea se corte en un guion, para que un teléfono o un número de pieza no se parta al llegar al margen; parece un guion normal pero es otro carácter.", "Evita que a linha quebre num hífen, para um telefone ou código de peça não rachar na margem; parece um hífen comum, mas é outro caractere.", "ハイフンで行が折り返されないようにします。電話番号や品番が行末で半分に割れるのを防ぐもので、見た目は普通のハイフンでも別の文字です。", "Verhindert den Zeilenumbruch am Bindestrich, damit eine Telefon- oder Artikelnummer am Rand nicht zerreißt; er sieht wie ein normaler Bindestrich aus, ist aber ein anderes Zeichen.", "Empêche le retour à la ligne sur un trait d’union, pour qu’un numéro de téléphone ou de pièce ne se coupe pas en deux ; il ressemble à un trait d’union normal mais c’est un autre caractère.", "hyphen पर पंक्ति टूटने से रोकता है, जिससे फ़ोन नंबर या पुरज़े का नंबर हाशिये पर आधा न कटे; दिखता साधारण hyphen जैसा है पर वर्ण अलग है।", "让行不在连字符处断开，电话号码或料号就不会在页边被劈成两半；它看着像普通连字符，其实是另一个字符。", "讓行不在連字號處斷開，電話號碼或料號就不會在頁邊被劈成兩半；它看著像普通連字號，其實是另一個字元。"],

  /* ───────── View ───────── */
  'word-formatting-marks': ["문단 기호와 빈칸, 쪽·구역 나누기 표시를 화면에 드러냅니다. 인쇄에는 나오지 않고, 지워지지 않는 빈 쪽이나 뜻 모를 여백의 정체는 대개 여기서 처음 보입니다.", "Reveals paragraph marks, spaces and the page or section breaks on screen; none of it prints, and a blank page you cannot delete usually explains itself the moment this is on.", "Muestra en pantalla las marcas de párrafo, los espacios y los saltos de página o sección; nada de eso se imprime, y una página en blanco que no se borra suele explicarse en cuanto esto se activa.", "Revela na tela as marcas de parágrafo, os espaços e as quebras de página ou seção; nada disso imprime, e aquela página em branco que não some costuma se explicar assim que isto é ligado.", "段落記号や空白、ページやセクションの区切りを画面に出します。印刷はされず、消せない白紙ページの正体はこれを出した瞬間にわかることが多いです。", "Macht Absatzmarken, Leerzeichen und Seiten- oder Abschnittswechsel auf dem Bildschirm sichtbar; gedruckt wird davon nichts, und eine unlöschbare leere Seite erklärt sich meist genau dann.", "Fait apparaître à l’écran les marques de paragraphe, les espaces et les sauts de page ou de section ; rien de tout cela ne s’imprime, et une page blanche impossible à supprimer s’explique souvent dès qu’on les affiche.", "पैराग्राफ़ चिह्न, रिक्त स्थान और पृष्ठ या section के विराम स्क्रीन पर दिखा देता है; छपता कुछ नहीं, और जो ख़ाली पृष्ठ मिटता ही नहीं उसका राज़ अक्सर इसे चालू करते ही खुल जाता है।", "在屏幕上显出段落标记、空格以及分页符和分节符；这些都不打印，而那页删不掉的空白页往往一开就明白了。", "在螢幕上顯出段落標記、空格以及分頁符和分節符；這些都不列印，而那頁刪不掉的空白頁往往一開就明白了。"],
  'word-word-count': ["낱말과 글자, 쪽과 문단 수를 한 창에 보여 줍니다. 글을 골라 두면 고른 만큼만 세고, 맥 Word에는 이 창에 붙은 기본 조합이 없어 아래 상태줄의 숫자를 눌러 엽니다.", "Shows the count of words, characters, pages and paragraphs in one box; with text selected it counts only the selection, and Word for Mac ships no binding for it — click the count in the status bar instead.", "Muestra en un cuadro el número de palabras, caracteres, páginas y párrafos; con texto seleccionado cuenta solo la selección, y Word for Mac no trae combinación: allí se pulsa el recuento de la barra de estado.", "Mostra numa caixa a contagem de palavras, caracteres, páginas e parágrafos; com texto selecionado conta só a seleção, e o Word for Mac não traz combinação — clique na contagem da barra de status.", "単語数と文字数、ページ数、段落数を一つの窓に出します。文字を選んでおくと選んだ分だけを数え、Mac の Word には既定の割り当てが無いので下のステータスバーの数字を押して開きます。", "Zeigt Wörter, Zeichen, Seiten und Absätze in einem Fenster; bei markiertem Text zählt es nur die Auswahl, und Word for Mac hat kein Kürzel dafür — dort klickt man die Zahl in der Statusleiste.", "Affiche dans une boîte le nombre de mots, de caractères, de pages et de paragraphes ; avec du texte sélectionné, il ne compte que la sélection, et Word for Mac n’a aucun raccourci : on clique le compteur de la barre d’état.", "एक बॉक्स में शब्द, अक्षर, पृष्ठ और पैराग्राफ़ की गिनती दिखाता है; लेख चुना हो तो केवल उतना गिनता है, और Mac के Word में इसका कोई संयोजन नहीं — नीचे status bar में गिनती पर क्लिक करें।", "在一个框里给出字数、字符数、页数和段落数；选了文字就只统计所选部分，而 Mac 版 Word 没有对应组合键，改成点状态栏上的字数。", "在一個框裡給出字數、字元數、頁數和段落數；選了文字就只統計所選部分，而 Mac 版 Word 沒有對應組合鍵，改成按狀態列上的字數。"],

  /* ───────── References ───────── */
  'word-footnote': ["커서 자리에 각주 번호를 넣고 그 쪽 아래로 데려갑니다. 번호는 자동이라 중간에 하나를 끼워도 뒤가 알아서 밀립니다.", "Drops a footnote number where the cursor is and takes you to the bottom of the page; the numbering is automatic, so inserting one in the middle renumbers the rest.", "Inserta un número de nota al pie donde está el cursor y te lleva al final de la página; la numeración es automática, así que insertar una en medio renumera las demás.", "Insere um número de nota de rodapé onde o cursor está e leva você ao pé da página; a numeração é automática, então inserir uma no meio renumera as outras.", "カーソルの位置に脚注番号を入れ、そのページの下へ連れて行きます。番号は自動なので、途中に一つ挟めば後ろが繰り下がります。", "Setzt an der Cursorposition eine Fußnotenzahl und springt an den Seitenfuß; die Nummerierung läuft automatisch, ein Einschub in der Mitte verschiebt alle folgenden.", "Insère un appel de note en bas de page à l’endroit du curseur et vous y emmène ; la numérotation est automatique, insérer une note au milieu renumérote les suivantes.", "cursor की जगह footnote संख्या डालकर उसी पृष्ठ के नीचे ले जाता है; क्रमांकन स्वतः होता है, बीच में एक जोड़ने पर आगे वाले अपने-आप खिसक जाते हैं।", "在光标处插入脚注编号并把你带到本页底部；编号是自动的，中间插一个后面的会自己往后排。", "在游標處插入註腳編號並把你帶到本頁底部；編號是自動的，中間插一個後面的會自己往後排。"],
  'word-endnote': ["문서나 구역 끝에 모이는 미주를 넣습니다. 윈도우는 D, 맥은 E를 쓰는 것이 이 짝의 함정입니다 — 두 기계를 함께 쓰면 각주 대신 미주가 들어갑니다.", "Inserts an endnote, which collects at the end of the document or section; the trap is that Windows uses D while the Mac uses E, so working on both machines you often get the wrong kind of note.", "Inserta una nota al final, que se agrupa al final del documento o de la sección; la trampa es que Windows usa D y Mac usa E, así que al alternar máquinas sale el tipo de nota equivocado.", "Insere uma nota de fim, que se junta no final do documento ou da seção; a pegadinha é que o Windows usa D e o Mac usa E, então alternando de máquina sai o tipo errado de nota.", "文末や節末にまとめられる文末脚注を入れます。落とし穴は Windows が D、Mac が E を使う点で、両方を使うと違う種類の注が入ります。", "Fügt eine Endnote ein, die sich am Ende von Dokument oder Abschnitt sammelt; die Falle: Windows nutzt D, der Mac E — beim Wechsel zwischen beiden landet leicht die falsche Notenart im Text.", "Insère une note de fin, regroupée à la fin du document ou de la section ; le piège est que Windows utilise D et le Mac E, si bien qu’en changeant de machine on obtient le mauvais type de note.", "endnote डालता है, जो दस्तावेज़ या section के अंत में इकट्ठी होती है; पेच यह है कि Windows पर D और Mac पर E है, इसलिए दोनों मशीनें चलाने पर ग़लत तरह का नोट पड़ जाता है।", "插入尾注，它们汇总在文档或节的末尾；坑在于 Windows 用 D、Mac 用 E，两台机器换着用很容易插错种类。", "插入章節附註，它們匯總在文件或章節的結尾；坑在於 Windows 用 D、Mac 用 E，兩台機器換著用很容易插錯種類。"],

  /* ───────── File ───────── */
  'word-save': ["지금 문서를 그 자리에 저장합니다. 자동 저장이 켜진 클라우드 문서에서는 이미 저장되고 있어서, 이 조합은 사실상 지금까지의 상태에 점을 찍는 일입니다.", "Saves the document where it already lives; on a cloud file with AutoSave on it is being saved anyway, so the keystroke mostly marks a point in time.", "Guarda el documento donde ya está; en un archivo en la nube con Autoguardado ya se guarda solo, así que la pulsación sirve sobre todo para marcar un punto.", "Salva o documento onde ele já está; num arquivo na nuvem com Salvamento Automático ele já é salvo sozinho, então a tecla serve mais para marcar um ponto no tempo.", "今の文書をその場所に保存します。自動保存が有効なクラウド上の文書ではすでに保存され続けているので、この操作は区切りを打つ意味に近いです。", "Speichert das Dokument dort, wo es liegt; bei einer Cloud-Datei mit AutoSpeichern wird ohnehin gespeichert, der Anschlag setzt dann eher eine Marke.", "Enregistre le document là où il se trouve ; sur un fichier en ligne avec l’enregistrement automatique, il l’est déjà, la frappe pose surtout un repère.", "दस्तावेज़ को उसी जगह सहेज देता है; AutoSave चालू क्लाउड फ़ाइल में वह पहले से सहेजा जा रहा होता है, इसलिए यह दबाव ज़्यादातर एक पड़ाव का निशान है।", "把文档存回原处；开着自动保存的云端文件本来就在存，这一下更像是给当前状态打个记号。", "把文件存回原處；開著自動儲存的雲端檔案本來就在存，這一下更像是給目前狀態打個記號。"],
  'word-save-as': ["이름과 자리, 파일 형식을 골라 다시 저장합니다. PDF로 내보내는 길도 여기 형식 목록 안에 있고, PDF에만 붙은 따로 된 조합은 없습니다.", "Saves again under a new name, place or file type; the way out to PDF is one of the types in that list, and there is no separate binding just for PDF.", "Guarda de nuevo con otro nombre, sitio o tipo de archivo; la salida a PDF es uno de los tipos de esa lista, y no hay combinación aparte solo para PDF.", "Salva de novo com outro nome, lugar ou tipo de arquivo; o caminho para PDF é um dos tipos dessa lista, e não existe combinação separada só para PDF.", "名前や場所、ファイル形式を選び直して保存します。PDF への書き出しもその形式一覧の中にあり、PDF だけに付いた別の組み合わせはありません。", "Speichert erneut unter anderem Namen, Ort oder Dateityp; der Weg zu PDF ist einer der Typen in dieser Liste, ein eigenes Kürzel nur für PDF gibt es nicht.", "Enregistre à nouveau sous un autre nom, un autre emplacement ou un autre type de fichier ; la sortie en PDF est l’un des types de cette liste, et aucun raccourci distinct n’existe pour le PDF.", "नया नाम, जगह या फ़ाइल प्रकार चुनकर दोबारा सहेजता है; PDF का रास्ता उसी प्रकार-सूची में है, और केवल PDF के लिए अलग संयोजन नहीं है।", "换名字、位置或文件类型再存一次；导出 PDF 就在这个类型列表里，并没有单独给 PDF 的组合键。", "換名稱、位置或檔案類型再存一次；匯出 PDF 就在這個類型清單裡，並沒有單獨給 PDF 的組合鍵。"],
  'word-print': ["인쇄 화면을 엽니다. 윈도우는 여기서 미리보기와 설정이 한 화면에 함께 나와, 미리보기만 따로 여는 단계가 없습니다.", "Opens printing; on Windows the preview and the settings share one screen, so there is no separate step just to look at the preview.", "Abre la impresión; en Windows la vista previa y los ajustes están en la misma pantalla, así que no hay un paso aparte solo para ver la previa.", "Abre a impressão; no Windows a prévia e as opções ficam na mesma tela, então não há um passo separado só para ver a prévia.", "印刷の画面を開きます。Windows では下見と設定が同じ画面に並ぶので、下見だけを別に開く手順はありません。", "Öffnet das Drucken; unter Windows liegen Vorschau und Einstellungen auf einem Bildschirm, ein eigener Schritt nur für die Vorschau entfällt.", "Ouvre l’impression ; sous Windows l’aperçu et les réglages tiennent dans le même écran, il n’y a donc pas d’étape distincte pour l’aperçu.", "छपाई की स्क्रीन खोलता है; Windows पर झलक और सेटिंग्स एक ही स्क्रीन पर हैं, इसलिए केवल झलक देखने का अलग चरण नहीं है।", "打开打印界面；Windows 上预览和设置在同一屏，不用再单独走一步看预览。", "開啟列印畫面；Windows 上預覽和設定在同一畫面，不用再單獨走一步看預覽。"],
  'word-hyperlink': ["고른 글에 링크를 답니다. 아무것도 고르지 않고 누르면 주소가 그대로 보이는 링크가 들어가고, 이미 링크인 자리에서 누르면 고치는 창이 열립니다.", "Attaches a link to the selection; with nothing selected you get a link that shows the address itself, and on an existing link it opens the edit box instead.", "Añade un enlace a lo seleccionado; sin selección se inserta un enlace que muestra la propia dirección, y sobre un enlace existente abre el cuadro de edición.", "Anexa um link à seleção; sem seleção entra um link que mostra o próprio endereço, e sobre um link existente abre a caixa de edição.", "選んだ文字にリンクを付けます。何も選ばずに押すとアドレスがそのまま見えるリンクが入り、すでにリンクの上で押すと編集の窓が開きます。", "Hängt einen Link an die Auswahl; ohne Auswahl entsteht ein Link, der die Adresse selbst zeigt, auf einem bestehenden Link öffnet sich das Bearbeitungsfeld.", "Attache un lien à la sélection ; sans sélection, on obtient un lien qui affiche l’adresse elle-même, et sur un lien existant la boîte d’édition s’ouvre.", "चुने हुए लेख पर link लगाता है; कुछ चुना न हो तो ऐसा link आता है जिसमें पता ही दिखता है, और पहले से मौजूद link पर दबाने से संपादन का बॉक्स खुलता है।", "给选中的文字加链接；什么都没选时插入的链接会直接显示网址，在已有链接上按则是打开编辑框。", "給選取的文字加連結；什麼都沒選時插入的連結會直接顯示網址，在已有連結上按則是開啟編輯框。"],

  /* ───────── Selection · Ribbon ───────── */
  'word-extend-selection': ["선택 확장 모드를 켭니다. 켜 있는 동안에는 방향키가 모두 선택을 넓히고, 두 번 세 번 누르면 낱말·문장·문단으로 자라며, Esc로 끄기 전까지는 타이핑도 이상하게 굴러갑니다.", "Turns on extend-selection mode; while it is on every arrow key grows the selection, repeated presses jump from word to sentence to paragraph, and until Esc switches it off ordinary typing behaves strangely.", "Activa el modo de extender selección; mientras está activo cada flecha amplía la selección, las pulsaciones repetidas pasan de palabra a frase y a párrafo, y hasta pulsar Esc escribir se vuelve raro.", "Liga o modo de estender seleção; enquanto está ligado cada seta amplia a seleção, toques repetidos vão de palavra a frase e a parágrafo, e até apertar Esc digitar fica estranho.", "選択の拡張モードを入れます。入っている間は矢印キーがすべて選択を広げ、続けて押すと語・文・段落へ育ち、Esc で切るまでは普通の入力もおかしくなります。", "Schaltet den Erweiterungsmodus der Auswahl ein; solange er läuft, vergrößert jede Pfeiltaste die Auswahl, wiederholtes Drücken geht von Wort zu Satz zu Absatz, und bis Esc ihn beendet, verhält sich das Tippen seltsam.", "Active le mode d’extension de la sélection ; tant qu’il est actif, chaque flèche agrandit la sélection, les pressions répétées passent du mot à la phrase puis au paragraphe, et jusqu’à Esc la saisie se comporte bizarrement.", "extend selection मोड चालू करता है; चालू रहते हर तीर कुंजी चयन बढ़ाती है, बार-बार दबाने पर शब्द से वाक्य और पैराग्राफ़ तक जाता है, और Esc से बंद करने तक सामान्य टाइपिंग भी अजीब लगती है।", "打开扩展选择模式；开着的时候每个方向键都在扩大选区，连按会从词扩到句再到段，按 Esc 关掉之前连正常输入都怪怪的。", "開啟擴展選取模式；開著的時候每個方向鍵都在擴大選取範圍，連按會從字擴到句再到段，按 Esc 關掉之前連正常輸入都怪怪的。"],
  'word-ribbon-search': ["리본의 검색 상자로 커서를 보내, 기능 이름을 쳐서 바로 실행합니다. Alt를 누르면 리본에 글자 힌트가 뜨는 이 방식은 윈도우만의 것이고, 맥 Office에는 그 힌트가 아예 없습니다.", "Puts the cursor in the ribbon Search box so you can run a command by name; the whole Alt key-tip system belongs to Windows, and Office for Mac has no key tips at all.", "Lleva el cursor al cuadro de búsqueda de la cinta para ejecutar un comando por su nombre; todo el sistema de sugerencias con Alt es de Windows, y Office for Mac no tiene esas sugerencias.", "Leva o cursor à caixa de pesquisa da faixa para você executar um comando pelo nome; todo o sistema de dicas de tecla com Alt é do Windows, e o Office for Mac não tem dicas nenhuma.", "リボンの検索ボックスへカーソルを送り、機能名を打って実行します。Alt を押すとリボンに文字のヒントが出るこの仕組みは Windows だけのもので、Mac の Office にはヒントがありません。", "Setzt den Cursor in das Suchfeld des Menübands, um einen Befehl über den Namen auszuführen; das ganze Alt-Zugriffstastensystem gehört zu Windows, Office for Mac kennt keine Zugriffstasten.", "Place le curseur dans la zone de recherche du ruban pour lancer une commande par son nom ; tout le système d’info-bulles de touches avec Alt appartient à Windows, Office for Mac n’en a aucune.", "cursor को ribbon के Search बॉक्स में भेजता है ताकि नाम लिखकर कोई कमांड चलाई जा सके; Alt दबाने पर ribbon में अक्षर-संकेत दिखने की यह व्यवस्था केवल Windows की है, Office for Mac में ऐसे संकेत ही नहीं हैं।", "把光标送进功能区的搜索框，输入功能名就能直接执行；按 Alt 在功能区显示字母提示这套机制只有 Windows 有，Mac 版 Office 根本没有提示。", "把游標送進功能區的搜尋框，輸入功能名稱就能直接執行；按 Alt 在功能區顯示字母提示這套機制只有 Windows 有，Mac 版 Office 根本沒有提示。"],

  /* ═════════ powerpoint ═════════ */

  /* ───────── Slideshow ───────── */
  'powerpoint-start-show': ["첫 장부터 전체 화면으로 발표를 시작합니다. 지금 몇 번째 장을 보고 있든 언제나 첫 장으로 돌아가고, 화면이 둘이면 발표는 바깥 화면으로 나갑니다.", "Runs the deck full screen from slide one; it always goes back to the first slide no matter which one you were editing, and with two displays the show moves to the external one.", "Ejecuta la presentación a pantalla completa desde la primera diapositiva; siempre vuelve al principio sin importar en qué diapositiva estabas, y con dos pantallas la proyección se va a la externa.", "Roda a apresentação em tela cheia a partir do primeiro slide; volta sempre ao começo, não importa em qual slide você estava, e com duas telas a exibição vai para a externa.", "一枚目から全画面で発表を始めます。どの枚を見ていても必ず先頭に戻り、画面が二つあれば本番は外側の画面へ出ます。", "Startet die Präsentation im Vollbild ab Folie eins; sie beginnt immer vorn, egal welche Folie gerade offen war, und bei zwei Bildschirmen läuft sie auf dem externen.", "Lance le diaporama en plein écran depuis la première diapositive ; il repart toujours du début, quelle que soit la diapositive en cours, et avec deux écrans la projection part sur l’écran externe.", "पहली slide से पूरे परदे पर प्रस्तुति शुरू करता है; आप किसी भी slide पर हों, यह हमेशा पहली पर लौटता है, और दो स्क्रीन हों तो प्रस्तुति बाहरी स्क्रीन पर जाती है।", "从第一张幻灯片开始全屏放映；不管你正在看第几张，它总是回到第一张，接了两块屏时放映会走到外接屏。", "從第一張投影片開始全螢幕放映；不管你正在看第幾張，它總是回到第一張，接了兩個螢幕時放映會走到外接螢幕。"],
  'powerpoint-start-from-current': ["지금 보고 있는 장부터 발표를 시작합니다. 발표 중에 잠깐 나와 한 줄 고친 뒤 그 자리로 돌아갈 때 쓰는 것이고, 숨긴 장은 여전히 건너뜁니다.", "Starts the show from the slide you are on — the one you want after ducking out to fix a line — and hidden slides are still skipped.", "Empieza la presentación en la diapositiva actual, justo lo que hace falta tras salir a corregir una línea, y las diapositivas ocultas siguen omitiéndose.", "Começa a apresentação no slide atual, o que você quer depois de sair para corrigir uma linha, e slides ocultos continuam sendo pulados.", "今見ている枚から発表を始めます。途中で抜けて一行直したあと元の場所へ戻るための操作で、非表示にした枚は変わらず飛ばされます。", "Startet die Präsentation bei der aktuellen Folie — genau richtig, nachdem man kurz ausgestiegen ist, um eine Zeile zu korrigieren; ausgeblendete Folien bleiben übersprungen.", "Démarre le diaporama à la diapositive courante — ce qu’il faut après être sorti corriger une ligne — et les diapositives masquées restent ignorées.", "जिस slide पर आप हैं, वहीं से प्रस्तुति शुरू करता है — बीच में निकलकर एक पंक्ति ठीक करने के बाद यही चाहिए — और छिपाई गई slides फिर भी छूट जाती हैं।", "从你当前这一张开始放映——中途退出改一行字后就用它回到原处——隐藏的幻灯片照旧跳过。", "從你目前這一張開始放映——中途退出改一行字後就用它回到原處——隱藏的投影片照舊跳過。"],
  'powerpoint-presenter-view': ["발표자용 화면을 띄웁니다 — 메모와 다음 장, 시간이 함께 보입니다. 화면이 하나뿐이면 이 화면이 그 하나를 차지하니, 실제 발표에서는 화면 두 개를 먼저 확인합니다.", "Opens the presenter screen with your notes, the next slide and a timer; with a single display it takes over that one screen, so check your second display before you rely on it.", "Abre la pantalla del presentador con las notas, la diapositiva siguiente y un cronómetro; con una sola pantalla ocupa esa, así que comprueba la segunda antes de confiar en ella.", "Abre a tela do apresentador com suas anotações, o próximo slide e um cronômetro; com uma única tela ela toma essa, então confira a segunda antes de depender dela.", "発表者用の画面を出します — メモ、次の枚、経過時間が並びます。画面が一つだけならその画面を占めるので、本番では二つ目の画面を先に確かめます。", "Öffnet die Referentenansicht mit Notizen, nächster Folie und Timer; bei nur einem Bildschirm belegt sie diesen — vor dem Ernstfall den zweiten Bildschirm prüfen.", "Ouvre l’écran du présentateur avec les notes, la diapositive suivante et un minuteur ; avec un seul écran il l’occupe entièrement, donc vérifiez le second écran avant de compter dessus.", "प्रस्तुतकर्ता की स्क्रीन खोलता है — नोट्स, अगली slide और घड़ी एक साथ; एक ही स्क्रीन हो तो वही भर जाती है, इसलिए असली प्रस्तुति से पहले दूसरी स्क्रीन जाँच लें।", "打开演讲者视图：备注、下一张和计时器一起显示；只有一块屏时它会占满这块屏，正式讲之前先确认第二块屏。", "開啟簡報者檢視畫面：備忘稿、下一張和計時器一起顯示；只有一個螢幕時它會佔滿這個螢幕，正式講之前先確認第二個螢幕。"],
  'powerpoint-next-slide': ["다음으로 넘깁니다. 발표 중에만 듣는 키라 편집 화면에서는 그냥 글자 N이 입력되고, 애니메이션이 걸린 장에서는 한 번에 한 동작씩 나아갑니다.", "Advances the show; it only listens while you are presenting — in edit view it just types the letter — and on an animated slide each press plays one step before the slide changes.", "Avanza la presentación; solo responde mientras presentas —en la vista de edición escribe la letra— y en una diapositiva animada cada pulsación reproduce un paso antes de cambiar.", "Avança a apresentação; só responde enquanto você apresenta — na visão de edição só digita a letra — e num slide animado cada toque toca um passo antes de virar.", "次へ進みます。発表中だけ効くキーで、編集画面では文字の N が入るだけです。動きを付けた枚では一押しごとに一段ずつ進みます。", "Blättert weiter; die Taste hört nur während der Präsentation zu — in der Bearbeitungsansicht tippt sie bloß den Buchstaben — und auf einer animierten Folie läuft pro Druck ein Schritt.", "Avance dans le diaporama ; la touche n’écoute qu’en mode présentation — en édition elle tape simplement la lettre — et sur une diapositive animée chaque pression joue une étape avant de changer.", "अगली पर बढ़ता है; यह कुंजी केवल प्रस्तुति के दौरान सुनती है — संपादन दृश्य में तो सिर्फ़ अक्षर टाइप होता है — और animation वाली slide पर हर दबाव एक चरण चलाता है।", "往后翻；这个键只在放映时管用，编辑视图里只会打出这个字母，带动画的一页则是按一下走一步再翻页。", "往後翻；這個鍵只在放映時管用，編輯檢視裡只會打出這個字母，帶動畫的一頁則是按一下走一步再翻頁。"],
  'powerpoint-previous-slide': ["앞으로 되돌립니다. 애니메이션도 거꾸로 한 단씩 물러나므로, 한 장 앞으로 곧장 가려면 여러 번 눌러야 할 수 있습니다.", "Steps the show backwards; animations rewind one step at a time as well, so getting to the previous slide can take several presses.", "Retrocede la presentación; las animaciones también rebobinan paso a paso, así que llegar a la diapositiva anterior puede costar varias pulsaciones.", "Volta na apresentação; as animações também rebobinam passo a passo, então chegar ao slide anterior pode exigir vários toques.", "前へ戻ります。動きも一段ずつ巻き戻るので、一枚前へ行くには何度か押すことがあります。", "Blättert zurück; auch Animationen laufen schrittweise rückwärts, bis zur vorigen Folie braucht es daher manchmal mehrere Anschläge.", "Recule dans le diaporama ; les animations se rembobinent aussi étape par étape, atteindre la diapositive précédente peut donc demander plusieurs pressions.", "पीछे लौटता है; animations भी एक-एक चरण उलटी चलती हैं, इसलिए पिछली slide तक पहुँचने में कई बार दबाना पड़ सकता है।", "往前退；动画也是一步步倒回去的，所以要退到上一页可能得按好几次。", "往前退；動畫也是一步步倒回去的，所以要退到上一頁可能得按好幾次。"],
  'powerpoint-go-to-slide': ["장 번호를 치고 확인하면 그 장으로 곧장 뜁니다. 발표 중에만 되고 누른 숫자는 화면에 보이지 않으며, 숨긴 장에도 이렇게는 갈 수 있습니다.", "Type a slide number and confirm to jump straight there; it works during the show only, the digits never appear on screen, and this is one way to reach a hidden slide.", "Escribe el número de diapositiva y confirma para saltar allí; solo funciona durante la presentación, los dígitos no se ven en pantalla y así se puede llegar incluso a una diapositiva oculta.", "Digite o número do slide e confirme para pular direto; funciona só durante a apresentação, os dígitos não aparecem na tela e assim dá para chegar até a um slide oculto.", "枚の番号を打って確定すると、その枚へ直接飛びます。発表中だけ有効で、打った数字は画面に出ず、非表示の枚へもこの方法なら行けます。", "Foliennummer tippen und bestätigen, dann springt die Präsentation direkt dorthin; das geht nur während der Vorführung, die Ziffern sind unsichtbar, und selbst ausgeblendete Folien lassen sich so erreichen.", "Tapez un numéro de diapositive puis validez pour y sauter ; cela ne marche qu’en cours de diaporama, les chiffres n’apparaissent pas à l’écran, et c’est un moyen d’atteindre une diapositive masquée.", "slide की संख्या टाइप करके पुष्टि करने पर सीधे वहीं पहुँच जाते हैं; यह केवल प्रस्तुति के दौरान चलता है, अंक परदे पर नहीं दिखते, और छिपाई गई slide तक भी इसी तरह पहुँचा जा सकता है।", "输入幻灯片编号再确认，就直接跳到那一张；只在放映时有效，输入的数字不会显示在屏幕上，隐藏的幻灯片也能这样到达。", "輸入投影片編號再確認，就直接跳到那一張；只在放映時有效，輸入的數字不會顯示在螢幕上，隱藏的投影片也能這樣到達。"],
  'powerpoint-black-screen': ["화면을 검게 가립니다. 발표는 멈춘 것이 아니라 그대로 돌고 있어서 한 번 더 누르면 돌아오는데, 이것을 모르면 프로젝터가 꺼졌다고 생각하게 됩니다.", "Blanks the screen to black; the show is still running and one more press brings it back, but people who do not know that decide the projector has died.", "Pone la pantalla en negro; la presentación sigue corriendo y otra pulsación la devuelve, pero quien no lo sabe da por muerto el proyector.", "Deixa a tela preta; a apresentação continua rodando e outro toque a traz de volta, mas quem não sabe conclui que o projetor morreu.", "画面を黒く覆います。発表は止まっておらずそのまま動いているので、もう一度押せば戻ります。これを知らないとプロジェクターが落ちたと思われます。", "Schaltet den Bildschirm auf Schwarz; die Präsentation läuft weiter und ein zweiter Druck holt sie zurück — wer das nicht weiß, hält den Projektor für ausgefallen.", "Passe l’écran au noir ; le diaporama continue de tourner et une seconde pression le ramène, mais qui l’ignore croit le projecteur mort.", "परदे को काला कर देता है; प्रस्तुति रुकती नहीं, चलती रहती है और दोबारा दबाने पर लौट आती है, पर यह न जानने वाले समझते हैं कि projector बंद हो गया।", "把屏幕变黑；放映并没有停，还在继续，再按一次就回来，不知道这点的人会以为投影仪坏了。", "把螢幕變黑；放映並沒有停，還在繼續，再按一次就回來，不知道這點的人會以為投影機壞了。"],
  'powerpoint-white-screen': ["화면을 하얗게 가립니다. 어두운 방에서 검은 화면 대신 쓰는 것이고, 역시 발표 중에만 듣습니다.", "Blanks the screen to white — the choice in a dark room where black looks like a failure — and like the black version it only answers during the show.", "Pone la pantalla en blanco, la opción en una sala oscura donde el negro parece una avería, y como aquel solo responde durante la presentación.", "Deixa a tela branca — a escolha numa sala escura, onde o preto parece defeito — e, como ele, só responde durante a apresentação.", "画面を白く覆います。暗い部屋で黒より使いやすい方で、こちらも発表中だけ効きます。", "Schaltet den Bildschirm auf Weiß — die Wahl im dunklen Raum, wo Schwarz wie ein Defekt wirkt — und hört ebenfalls nur während der Vorführung zu.", "Passe l’écran au blanc — le choix dans une salle sombre où le noir ressemble à une panne — et, comme lui, ne répond qu’en cours de diaporama.", "परदे को सफ़ेद कर देता है — अँधेरे कमरे में काले के बजाय यही ठीक लगता है — और यह भी केवल प्रस्तुति के दौरान सुनता है।", "把屏幕变白；暗房里黑屏容易被当成故障，就用这个，它同样只在放映时有效。", "把螢幕變白；暗房裡黑屏容易被當成故障，就用這個，它同樣只在放映時有效。"],
  'powerpoint-laser-pointer': ["마우스 커서를 붉은 레이저 점으로 바꿉니다. 발표 중에만 듣는 키로, 편집 화면에서 같은 조합은 글을 왼쪽에 맞추는 일을 합니다.", "Turns the mouse pointer into a red laser dot; it works only while presenting, and in edit view the same combination aligns text to the left instead.", "Convierte el puntero en un punto láser rojo; solo funciona al presentar, y en la vista de edición esa misma combinación alinea el texto a la izquierda.", "Transforma o ponteiro num ponto laser vermelho; só funciona apresentando, e na visão de edição a mesma combinação alinha o texto à esquerda.", "マウスの矢印を赤いレーザーの点に変えます。発表中だけ効くキーで、編集画面では同じ組み合わせが文字を左に寄せます。", "Verwandelt den Mauszeiger in einen roten Laserpunkt; das geht nur während der Präsentation, in der Bearbeitungsansicht richtet dieselbe Kombination Text links aus.", "Change le pointeur en point laser rouge ; cela ne marche qu’en présentation, et en mode édition la même combinaison aligne le texte à gauche.", "माउस के तीर को लाल laser बिंदु बना देता है; यह केवल प्रस्तुति के दौरान चलता है, और संपादन दृश्य में वही संयोजन लेख को बाएँ लगा देता है।", "把鼠标指针变成红色激光点；只在放映时管用，编辑视图里同一个组合是把文字靠左对齐。", "把滑鼠指標變成紅色雷射點；只在放映時管用，編輯檢視裡同一個組合是把文字靠左對齊。"],
  'powerpoint-pen': ["커서를 펜으로 바꿔 발표 중에 화면에 직접 그립니다. 발표를 끝낼 때 그린 것을 남길지 묻고, 편집 화면에서 같은 조합은 인쇄입니다.", "Turns the pointer into a pen so you can draw on the slide while presenting; ending the show asks whether to keep the ink, and in edit view the same combination prints.", "Convierte el puntero en un lápiz para dibujar sobre la diapositiva mientras presentas; al terminar pregunta si conservar la tinta, y en la vista de edición esa combinación imprime.", "Transforma o ponteiro numa caneta para você desenhar no slide durante a apresentação; ao terminar ele pergunta se guarda a tinta, e na visão de edição a mesma combinação imprime.", "矢印をペンに変え、発表中に画面へ直接書き込めます。発表を終えるときに書いたものを残すか聞かれ、編集画面では同じ組み合わせが印刷になります。", "Macht aus dem Zeiger einen Stift, mit dem man während der Präsentation auf die Folie schreibt; am Ende fragt PowerPoint, ob die Freihandlinien bleiben sollen, in der Bearbeitungsansicht druckt dieselbe Kombination.", "Change le pointeur en stylet pour dessiner sur la diapositive en pleine présentation ; à la fin, PowerPoint demande s’il faut garder l’encre, et en édition la même combinaison imprime.", "तीर को pen बना देता है ताकि प्रस्तुति के दौरान slide पर सीधे लिखा जा सके; शो ख़त्म करते समय पूछता है कि स्याही रखनी है या नहीं, और संपादन दृश्य में वही संयोजन छपाई है।", "把指针换成笔，放映中直接在幻灯片上画；结束放映时会问要不要留下墨迹，而编辑视图里同一个组合是打印。", "把指標換成筆，放映中直接在投影片上畫；結束放映時會問要不要留下墨跡，而編輯檢視裡同一個組合是列印。"],
  'powerpoint-eraser': ["지우개를 집어 그려 둔 선을 지웁니다. 맥은 Cmd가 아니라 Shift 조합이고, 누른 뒤 선을 눌러야 한 줄씩 지워집니다.", "Picks up the eraser for ink you drew; the Mac uses a Shift combination rather than Cmd, and you then click a stroke to remove it one at a time.", "Toma la goma para borrar la tinta dibujada; en Mac es una combinación con Shift y no con Cmd, y luego hay que hacer clic en cada trazo.", "Pega a borracha para apagar a tinta desenhada; no Mac é uma combinação com Shift, não com Cmd, e depois você clica em cada traço.", "消しゴムを持って書いた線を消します。Mac は Cmd ではなく Shift の組み合わせで、押したあと線をクリックして一本ずつ消します。", "Nimmt den Radierer für gezeichnete Linien; der Mac nutzt eine Shift- statt einer Cmd-Kombination, und man klickt dann Strich für Strich.", "Prend la gomme pour l’encre tracée ; le Mac utilise une combinaison avec Shift et non avec Cmd, puis on clique chaque trait un à un.", "खींची गई स्याही मिटाने के लिए रबर उठाता है; Mac पर यह Cmd नहीं, Shift वाला संयोजन है, और फिर हर लकीर पर क्लिक करके एक-एक मिटाते हैं।", "拿起橡皮擦掉画上去的墨迹；Mac 用的是 Shift 组合而不是 Cmd，按完还要点一笔才擦掉一笔。", "拿起橡皮擦掉畫上去的墨跡；Mac 用的是 Shift 組合而不是 Cmd，按完還要點一筆才擦掉一筆。"],
  'powerpoint-arrow-pointer': ["펜이나 레이저를 끄고 보통 화살표로 돌아옵니다. 발표 중 이야기이고, 편집 화면에서 같은 조합은 장 안의 개체를 모두 고르는 일입니다.", "Brings the ordinary arrow back after the pen or the laser; that is the presenting meaning, while in edit view the same combination selects every object on the slide.", "Devuelve la flecha normal después del lápiz o el láser; ese es su sentido al presentar, mientras que en la vista de edición esa combinación selecciona todos los objetos de la diapositiva.", "Traz a seta comum de volta depois da caneta ou do laser; esse é o sentido durante a apresentação, já na visão de edição a mesma combinação seleciona todos os objetos do slide.", "ペンやレーザーをやめて普通の矢印に戻します。発表中の話で、編集画面では同じ組み合わせが枚の中の図形をすべて選びます。", "Holt den normalen Zeiger nach Stift oder Laser zurück; das gilt während der Präsentation, in der Bearbeitungsansicht markiert dieselbe Kombination alle Objekte der Folie.", "Ramène la flèche ordinaire après le stylet ou le laser ; c’est le sens en présentation, alors qu’en édition la même combinaison sélectionne tous les objets de la diapositive.", "pen या laser बंद करके सामान्य तीर वापस लाता है; यह अर्थ प्रस्तुति के दौरान है, संपादन दृश्य में वही संयोजन slide की सारी वस्तुएँ चुन लेता है।", "用完笔或激光后把普通箭头找回来；这是放映时的意思，编辑视图里同一个组合是选中这一页所有对象。", "用完筆或雷射後把普通箭頭找回來；這是放映時的意思，編輯檢視裡同一個組合是選取這一頁所有物件。"],
  'powerpoint-end-show': ["발표를 끝내고 편집 화면으로 돌아옵니다. 펜으로 그린 것이 있으면 남길지 버릴지 먼저 묻는데, 급히 넘기다 남긴다고 누르면 그 낙서가 파일에 들어갑니다.", "Leaves the show and returns to editing; if you drew with the pen it asks whether to keep or discard the ink first, and a hurried Keep writes those scribbles into the file.", "Sale de la presentación y vuelve a la edición; si dibujaste con el lápiz pregunta antes si conservar o descartar la tinta, y un Conservar apresurado mete esos garabatos en el archivo.", "Sai da apresentação e volta à edição; se você desenhou com a caneta, ele pergunta antes se guarda ou descarta a tinta, e um Guardar apressado grava os rabiscos no arquivo.", "発表を終えて編集画面へ戻ります。ペンで書いたものがあると残すか捨てるかを先に聞かれ、慌てて残すを押すとその落書きがファイルに入ります。", "Beendet die Vorführung und kehrt zur Bearbeitung zurück; gibt es Freihandlinien, fragt PowerPoint zuerst nach Behalten oder Verwerfen — ein hastiges Behalten schreibt das Gekritzel in die Datei.", "Quitte le diaporama et revient à l’édition ; si vous avez dessiné, il demande d’abord s’il faut garder ou jeter l’encre, et un Garder précipité inscrit ces gribouillis dans le fichier.", "प्रस्तुति ख़त्म करके संपादन पर लौटता है; pen से कुछ खींचा हो तो पहले पूछता है कि स्याही रखें या छोड़ें, और जल्दी में रखें दबाने से वे लकीरें फ़ाइल में चली जाती हैं।", "结束放映回到编辑；若你用笔画过，它会先问保留还是丢弃墨迹，慌忙点保留就把那些涂画写进文件了。", "結束放映回到編輯；若你用筆畫過，它會先問保留還是丟棄墨跡，慌忙按保留就把那些塗畫寫進檔案了。"],

  /* ───────── Slides ───────── */
  'powerpoint-new-slide': ["지금 장 다음에 새 장을 넣습니다. 맥에서는 Cmd+M이 창을 내리는 macOS 조합이라 다른 조합으로 옮겨 갔고, 새 장은 앞 장과 같은 레이아웃을 물려받습니다.", "Adds a slide after the current one; the Mac had to move this because Cmd+M minimises the window there, and the new slide inherits the layout of the one before it.", "Añade una diapositiva después de la actual; en Mac hubo que cambiar la combinación porque Cmd+M minimiza la ventana, y la nueva hereda el diseño de la anterior.", "Adiciona um slide depois do atual; no Mac a combinação teve de mudar porque Cmd+M minimiza a janela, e o novo herda o layout do anterior.", "今の枚の次に新しい枚を入れます。Mac では Cmd+M が窓をしまう macOS の割り当てなので別の組み合わせに移り、新しい枚は前の枚のレイアウトを受け継ぎます。", "Fügt nach der aktuellen eine neue Folie ein; am Mac musste das Kürzel weichen, weil Cmd+M dort das Fenster minimiert, und die neue Folie erbt das Layout der vorherigen.", "Ajoute une diapositive après celle en cours ; sur Mac le raccourci a dû bouger car Cmd+M y réduit la fenêtre, et la nouvelle hérite de la disposition de la précédente.", "मौजूदा slide के बाद नई slide जोड़ता है; Mac पर Cmd+M खिड़की छोटी करता है, इसलिए संयोजन बदलना पड़ा, और नई slide पिछली का layout अपना लेती है।", "在当前这一张后面插入新幻灯片；Mac 上 Cmd+M 是把窗口最小化，所以换了别的组合，新的一张会继承前一张的版式。", "在目前這一張後面插入新投影片；Mac 上 Cmd+M 是把視窗縮到最小，所以換了別的組合，新的一張會繼承前一張的版面配置。"],
  'powerpoint-duplicate-slide': ["장 하나를 통째로 복제해 바로 뒤에 놓습니다. 메모와 애니메이션, 전환까지 함께 따라오고, 개체 하나를 복제하는 조합과는 서로 다릅니다.", "Copies the whole slide in place, right after the original; the notes, the animations and the transition come along, and it is a different combination from duplicating a single object.", "Copia la diapositiva completa justo detrás de la original; las notas, las animaciones y la transición vienen con ella, y es una combinación distinta de duplicar un objeto.", "Copia o slide inteiro logo depois do original; anotações, animações e transição vêm junto, e é uma combinação diferente da de duplicar um objeto.", "枚を丸ごと複製してすぐ後ろに置きます。メモや動き、切り替えまで一緒に付いてきて、図形一つを複製する組み合わせとは別です。", "Verdoppelt die ganze Folie direkt hinter dem Original; Notizen, Animationen und Übergang kommen mit, und es ist ein anderes Kürzel als das Duplizieren eines einzelnen Objekts.", "Copie la diapositive entière juste après l’originale ; les notes, les animations et la transition suivent, et c’est un raccourci différent de celui qui duplique un objet.", "पूरी slide की नक़ल बनाकर मूल के ठीक बाद रख देता है; notes, animations और transition भी साथ आते हैं, और यह किसी एक वस्तु की नक़ल बनाने वाले संयोजन से अलग है।", "把整张幻灯片复制一份放在原件后面；备注、动画和切换效果都跟着走，它和复制单个对象是两个不同的组合。", "把整張投影片複製一份放在原件後面；備忘稿、動畫和切換效果都跟著走，它和複製單一物件是兩個不同的組合。"],
  'powerpoint-move-slide-up': ["고른 장을 순서에서 한 칸 위로 올립니다. 왼쪽 축소판이나 여러 장 보기에서 장을 골라 둔 상태여야 하고, 커서가 글 속에 있으면 순서는 꿈쩍도 하지 않습니다.", "Moves the selected slide one position earlier; the slide itself has to be selected in the thumbnail pane or slide sorter — with the cursor sitting in text nothing in the order budges.", "Sube la diapositiva seleccionada una posición; la diapositiva debe estar seleccionada en el panel de miniaturas o en el clasificador, porque con el cursor dentro del texto el orden no se mueve.", "Sobe o slide selecionado uma posição; o slide precisa estar selecionado no painel de miniaturas ou no classificador, pois com o cursor dentro do texto a ordem não se move.", "選んだ枚を順番で一つ上へ動かします。左のサムネイルか一覧で枚そのものを選んでいる必要があり、カーソルが文字の中にあると順番は動きません。", "Schiebt die markierte Folie eine Position nach vorn; die Folie muss im Miniaturbereich oder in der Foliensortierung markiert sein — steht der Cursor im Text, rührt sich die Reihenfolge nicht.", "Remonte la diapositive sélectionnée d’une position ; il faut que la diapositive elle-même soit sélectionnée dans le volet des miniatures ou la trieuse — curseur dans le texte, l’ordre ne bouge pas.", "चुनी हुई slide को क्रम में एक स्थान ऊपर ले जाता है; slide स्वयं thumbnail pane या slide sorter में चुनी होनी चाहिए — cursor लेख के भीतर हो तो क्रम हिलता ही नहीं।", "把选中的幻灯片在顺序里往前挪一位；必须在缩略图窗格或幻灯片浏览里选中这一张，光标停在文字里时顺序一动不动。", "把選取的投影片在順序裡往前挪一位；必須在縮圖窗格或投影片瀏覽裡選取這一張，游標停在文字裡時順序一動不動。"],
  'powerpoint-move-slide-down': ["고른 장을 순서에서 한 칸 아래로 내립니다. 여러 장을 함께 골라 두면 덩어리째 움직이고, 구역을 골랐으면 구역 전체가 내려갑니다.", "Moves the selected slide one position later; select several and they travel as a block, and with a section selected the whole section moves.", "Baja la diapositiva seleccionada una posición; si eliges varias se mueven en bloque, y con una sección seleccionada baja la sección entera.", "Desce o slide selecionado uma posição; selecione vários e eles andam em bloco, e com uma seção selecionada a seção inteira desce.", "選んだ枚を順番で一つ下へ動かします。複数選んでおけば塊のまま動き、区域を選んでいれば区域ごと下がります。", "Schiebt die markierte Folie eine Position nach hinten; mehrere markierte wandern als Block, und bei markiertem Abschnitt zieht der ganze Abschnitt mit.", "Descend la diapositive sélectionnée d’une position ; plusieurs sélectionnées se déplacent en bloc, et avec une section sélectionnée c’est toute la section qui bouge.", "चुनी हुई slide को क्रम में एक स्थान नीचे ले जाता है; कई चुनी हों तो वे एक गुच्छे में चलती हैं, और section चुना हो तो पूरा section नीचे जाता है।", "把选中的幻灯片在顺序里往后挪一位；选了好几张就整块一起走，选中某一节则整节下移。", "把選取的投影片在順序裡往後挪一位；選了好幾張就整塊一起走，選取某一節則整節下移。"],
  'powerpoint-outline-pane-toggle': ["왼쪽 창을 축소판과 개요 사이에서 바꿉니다. 개요 쪽에서는 제목과 글머리표를 글처럼 이어 쓸 수 있어서, 장을 빨리 쌓아 올릴 때 가장 빠른 길입니다.", "Swaps the left pane between the thumbnails and the outline; in the outline you type titles and bullets as plain text, which is the fastest way to rough out a deck.", "Cambia el panel izquierdo entre las miniaturas y el esquema; en el esquema escribes títulos y viñetas como texto plano, la vía más rápida para montar una presentación.", "Alterna o painel da esquerda entre as miniaturas e a estrutura de tópicos; na estrutura você digita títulos e marcadores como texto puro, o jeito mais rápido de esboçar a apresentação.", "左の窓をサムネイルとアウトラインで切り替えます。アウトラインでは見出しと箇条書きを文字のまま打てるので、枚を素早く組み上げるのに一番速い道です。", "Wechselt den linken Bereich zwischen Miniaturen und Gliederung; in der Gliederung tippt man Titel und Aufzählungen als reinen Text — der schnellste Weg, eine Präsentation zu entwerfen.", "Bascule le volet de gauche entre les miniatures et le plan ; dans le plan, on tape titres et puces comme du texte brut, la voie la plus rapide pour ébaucher un diaporama.", "बाईं ओर के pane को thumbnails और outline के बीच बदलता है; outline में शीर्षक और bullet सादे लेख की तरह टाइप होते हैं, प्रस्तुति खड़ी करने का यही सबसे तेज़ रास्ता है।", "把左侧窗格在缩略图和大纲之间切换；大纲里可以像写文本一样打标题和项目符号，这是快速搭出一份演示文稿最快的路。", "把左側窗格在縮圖和大綱之間切換；大綱裡可以像寫文字一樣打標題和項目符號，這是快速搭出一份簡報最快的路。"],

  /* ───────── Outline ───────── */
  'powerpoint-promote-bullet': ["글머리표를 한 단 위로 올립니다. 맥은 방향키가 아니라 대괄호를 쓰고, 글 상자나 개요 안이 아니면 아무 일도 일어나지 않습니다.", "Raises the bullet one outline level; the Mac uses bracket keys rather than arrows, and outside a text placeholder or the outline nothing happens at all.", "Sube la viñeta un nivel; en Mac se usan los corchetes y no las flechas, y fuera de un marcador de texto o del esquema no ocurre nada.", "Sobe o marcador um nível; no Mac usam-se os colchetes e não as setas, e fora de um espaço reservado de texto ou da estrutura nada acontece.", "箇条書きを一段上げます。Mac は矢印ではなく角括弧を使い、文字のプレースホルダーやアウトラインの外では何も起きません。", "Hebt den Aufzählungspunkt eine Ebene an; der Mac nutzt Klammertasten statt Pfeile, und außerhalb eines Textplatzhalters oder der Gliederung passiert gar nichts.", "Remonte la puce d’un niveau ; le Mac utilise les crochets et non les flèches, et hors d’un espace réservé de texte ou du plan, rien ne se produit.", "bullet को एक स्तर ऊपर उठाता है; Mac पर तीर नहीं, bracket कुंजियाँ चलती हैं, और text placeholder या outline के बाहर कुछ नहीं होता।", "把项目符号提升一级；Mac 用的是方括号而不是方向键，而且不在文本占位符或大纲里时什么都不会发生。", "把項目符號升一級；Mac 用的是方括號而不是方向鍵，而且不在文字版面配置區或大綱裡時什麼都不會發生。"],
  'powerpoint-demote-bullet': ["글머리표를 한 단 아래로 내립니다. 줄 맨 앞에서 Tab을 눌러도 같은 일이 되지만, 표 안에서 Tab은 다음 칸으로 넘어가는 뜻이라 헷갈리기 쉽습니다.", "Drops the bullet one level; Tab at the start of the line does the same inside a placeholder, but in a table Tab means next cell, which is where the confusion starts.", "Baja la viñeta un nivel; Tab al principio de la línea hace lo mismo dentro de un marcador, pero en una tabla Tab significa celda siguiente, y ahí empieza la confusión.", "Desce o marcador um nível; Tab no início da linha faz o mesmo dentro de um espaço reservado, mas numa tabela Tab significa próxima célula, e aí começa a confusão.", "箇条書きを一段下げます。行頭で Tab を押しても同じですが、表の中の Tab は次のセルへ移る意味なので取り違えやすいところです。", "Setzt den Aufzählungspunkt eine Ebene tiefer; im Platzhalter tut Tab am Zeilenanfang dasselbe, in einer Tabelle bedeutet Tab jedoch nächste Zelle — hier beginnt die Verwirrung.", "Descend la puce d’un niveau ; dans un espace réservé, Tab en début de ligne fait pareil, mais dans un tableau Tab signifie cellule suivante, et la confusion commence là.", "bullet को एक स्तर नीचे लाता है; placeholder के भीतर पंक्ति की शुरुआत में Tab भी वही करता है, पर तालिका में Tab का अर्थ अगला cell है, गड़बड़ यहीं से शुरू होती है।", "把项目符号降一级；在占位符里，行首按 Tab 效果一样，但在表格里 Tab 是跳到下一格，混乱就从这里开始。", "把項目符號降一級；在版面配置區裡，行首按 Tab 效果一樣，但在表格裡 Tab 是跳到下一格，混亂就從這裡開始。"],

  /* ───────── Objects ───────── */
  'powerpoint-group': ["고른 개체 여러 개를 하나로 묶습니다. 두 개 이상이어야 듣고, 묶은 뒤에는 애니메이션도 한 덩어리로 걸리기 때문에 함께 움직여야 하는 것끼리만 묶습니다.", "Binds the selected objects into one; it needs two or more, and a group animates as a single thing, so group only what should move together.", "Une los objetos seleccionados en uno; hace falta dos o más, y un grupo se anima como una sola cosa, así que agrupa solo lo que deba moverse junto.", "Une os objetos selecionados em um; precisa de dois ou mais, e um grupo anima como uma coisa só, então agrupe apenas o que deve se mover junto.", "選んだ図形をひとつにまとめます。二つ以上でないと効かず、まとめた後は動きも一塊に付くので、一緒に動くべきものだけをまとめます。", "Fasst die markierten Objekte zu einem zusammen; es braucht mindestens zwei, und eine Gruppe animiert als ein Ganzes — gruppieren Sie also nur, was sich gemeinsam bewegen soll.", "Réunit les objets sélectionnés en un seul ; il en faut au moins deux, et un groupe s’anime comme un bloc, donc ne groupez que ce qui doit bouger ensemble.", "चुनी हुई वस्तुओं को एक में बाँध देता है; दो या अधिक चाहिए, और समूह पर animation एक ही इकाई की तरह लगती है, इसलिए वही बाँधें जो साथ चलना चाहिए।", "把选中的多个对象并成一个；至少要两个，而且成组后动画是按一个整体走的，所以只把该一起动的东西组在一起。", "把選取的多個物件併成一個；至少要兩個，而且成組後動畫是按一個整體走的，所以只把該一起動的東西組在一起。"],
  'powerpoint-ungroup': ["묶음을 풀어 개체를 따로 떼어 놓습니다. SmartArt나 차트에 이것을 걸면 그냥 도형 무더기로 바뀌어 다시 SmartArt로 되돌릴 수 없으니, 실행 취소 말고는 되돌릴 길이 없습니다.", "Breaks a group back into separate objects; run it on SmartArt or a chart and you get a heap of plain shapes that can never be turned back, with Undo as the only way out.", "Deshace el grupo en objetos separados; aplicado a un SmartArt o a un gráfico deja un montón de formas simples que ya no vuelven a ser SmartArt, y solo deshacer te salva.", "Desfaz o grupo em objetos separados; aplicado a um SmartArt ou a um gráfico, sobra um monte de formas comuns que não voltam mais, e só o desfazer salva.", "まとまりを解いて図形を別々にします。SmartArt やグラフにこれを当てると単なる図形の集まりになり、SmartArt には戻せません — 元に戻す操作しか救いはありません。", "Löst die Gruppe in einzelne Objekte auf; auf SmartArt oder ein Diagramm angewendet bleibt ein Haufen einfacher Formen, der sich nie zurückverwandeln lässt — nur Rückgängig hilft.", "Défait le groupe en objets distincts ; appliqué à un SmartArt ou à un graphique, il ne reste qu’un tas de formes simples impossibles à reconvertir, et seule l’annulation sauve la mise.", "समूह तोड़कर वस्तुओं को अलग कर देता है; SmartArt या chart पर चलाने से वह साधारण आकृतियों का ढेर बन जाता है जो फिर SmartArt नहीं बनता, बचाव केवल undo है।", "把组拆回单个对象；对 SmartArt 或图表用它，会变成一堆普通形状，再也变不回去，唯一的退路是撤销。", "把群組拆回單個物件；對 SmartArt 或圖表用它，會變成一堆普通形狀，再也變不回去，唯一的退路是復原。"],
  'powerpoint-send-backward': ["개체를 쌓임 순서에서 한 칸 뒤로 보냅니다. 맨 뒤까지 가는 것이 아니라 한 칸씩이라, 겹친 도형이 여럿이면 그만큼 여러 번 눌러야 합니다.", "Sends the object back one position in the stack; it is one step, not all the way to the bottom, so a pile of overlapping shapes takes that many presses.", "Envía el objeto una posición atrás en la pila; es un paso, no hasta el fondo, así que un montón de formas superpuestas exige tantas pulsaciones como capas.", "Envia o objeto uma posição para trás na pilha; é um passo, não até o fundo, então um monte de formas sobrepostas exige tantos toques quanto camadas.", "図形を重なり順で一つ後ろへ送ります。最背面まで一気に行くのではなく一段ずつなので、重なった図形が多いとその回数だけ押します。", "Schickt das Objekt eine Position im Stapel zurück; es ist ein Schritt, nicht ganz nach hinten, bei vielen überlappenden Formen also entsprechend viele Anschläge.", "Renvoie l’objet d’une position en arrière dans la pile ; c’est un cran, pas jusqu’au fond, donc un empilement de formes demande autant de pressions que de couches.", "वस्तु को परतों के क्रम में एक स्थान पीछे भेजता है; यह एक क़दम है, सबसे पीछे तक नहीं, इसलिए कई ओवरलैप आकृतियाँ हों तो उतनी ही बार दबाना पड़ता है।", "把对象在叠放次序里往后移一层；是一层一层，不是直接到最底，重叠的形状多就得按同样多次。", "把物件在疊放順序裡往後移一層；是一層一層，不是直接到最底，重疊的形狀多就得按同樣多次。"],
  'powerpoint-bring-forward': ["개체를 쌓임 순서에서 한 칸 앞으로 꺼냅니다. 뒤로 보내기와 짝이고, 맨 앞으로 한 번에 올리는 명령은 Arrange 메뉴에 따로 있습니다.", "Brings the object forward one position; it is the twin of send backward, and the bring-it-all-the-way-to-the-front command is a separate item in the Arrange menu.", "Trae el objeto una posición adelante; es el gemelo de enviar atrás, y traer al frente de una vez es otra orden del menú Arrange.", "Traz o objeto uma posição à frente; é o gêmeo de enviar para trás, e trazer para a frente de uma vez é outro comando no menu Arrange.", "図形を重なり順で一つ前へ出します。後ろへ送る操作の対で、最前面へ一度に上げる命令は Arrange のメニューに別にあります。", "Holt das Objekt eine Position nach vorn; es ist das Gegenstück zum Zurückschicken, und ganz nach vorn holen ist ein eigener Befehl im Menü Arrange.", "Fait avancer l’objet d’une position ; c’est le jumeau du renvoi en arrière, et mettre au premier plan d’un coup est une commande distincte du menu Arrange.", "वस्तु को परतों के क्रम में एक स्थान आगे लाता है; यह पीछे भेजने का जोड़ीदार है, और एक ही बार में सबसे आगे लाने की आज्ञा Arrange मेनू में अलग है।", "把对象在叠放次序里往前提一层；它和往后移是一对，一次提到最前面是 Arrange 菜单里另一条命令。", "把物件在疊放順序裡往前提一層；它和往後移是一對，一次提到最前面是 Arrange 選單裡另一條命令。"],
  'powerpoint-duplicate-object': ["고른 개체를 복제해 조금 비켜 놓습니다. 이어서 다시 누르면 같은 간격으로 계속 놓이기 때문에, 같은 도형을 줄줄이 놓을 때 편합니다.", "Duplicates the selected object slightly offset from the original; press it again and the offset repeats, which lines up a row of identical shapes.", "Duplica el objeto seleccionado un poco desplazado; al repetir, el desplazamiento se mantiene y así se alinea una fila de formas iguales.", "Duplica o objeto selecionado um pouco deslocado; repetindo, o deslocamento se mantém e alinha uma fileira de formas iguais.", "選んだ図形を少しずらして複製します。続けて押すと同じ間隔で置かれていくので、同じ図形を並べるのに便利です。", "Verdoppelt das markierte Objekt leicht versetzt; bei Wiederholung bleibt der Versatz gleich und reiht identische Formen auf.", "Duplique l’objet sélectionné légèrement décalé ; en répétant, le décalage se reproduit et aligne une série de formes identiques.", "चुनी हुई वस्तु की नक़ल थोड़ा हटाकर रखता है; दोबारा दबाने पर वही अंतर बना रहता है, जिससे एक जैसी आकृतियों की कतार बन जाती है।", "把选中的对象复制一份，稍微错开放着；再按一次仍按同样的间距摆，正好排出一行相同的形状。", "把選取的物件複製一份，稍微錯開放著；再按一次仍按同樣的間距擺，正好排出一列相同的形狀。"],
  'powerpoint-select-next-object': ["장 안의 개체를 하나씩 돌며 고릅니다. 글 상자 안에 커서가 있을 때는 같은 키가 들여쓰기가 되니, 먼저 Esc로 글에서 빠져나와야 개체가 잡힙니다.", "Cycles through the objects on the slide one at a time; with the cursor inside a text box the same key indents instead, so press Esc to leave the text first.", "Recorre los objetos de la diapositiva uno a uno; con el cursor dentro de un cuadro de texto la misma tecla sangra, así que pulsa Esc para salir del texto antes.", "Percorre os objetos do slide um a um; com o cursor dentro de uma caixa de texto a mesma tecla recua, então aperte Esc para sair do texto primeiro.", "枚の中の図形を一つずつ順に選びます。文字の箱にカーソルがあると同じキーが字下げになるので、先に Esc で文字から抜けます。", "Wandert einzeln durch die Objekte der Folie; steht der Cursor in einem Textfeld, rückt dieselbe Taste stattdessen ein — erst mit Esc den Text verlassen.", "Parcourt un à un les objets de la diapositive ; le curseur dans une zone de texte, la même touche indente, il faut donc d’abord sortir du texte avec Esc.", "slide की वस्तुओं को एक-एक करके चुनता है; cursor किसी text box के भीतर हो तो वही कुंजी indent कर देती है, इसलिए पहले Esc से लेख से बाहर आएँ।", "在这一页的对象之间逐个循环选取；光标在文本框里时同一个键是缩进，所以要先按 Esc 退出文字。", "在這一頁的物件之間逐個循環選取；游標在文字方塊裡時同一個鍵是縮排，所以要先按 Esc 離開文字。"],
  'powerpoint-paste-special': ["붙일 형식을 골라 붙입니다 — 그림으로, 또는 서식 없는 글로. 맥은 Cmd만이 아니라 Ctrl까지 함께 누르는 드문 조합입니다.", "Pastes in a form you choose — as a picture, or as unformatted text; the Mac is one of the rare places that wants Ctrl alongside Cmd.", "Pega en el formato que elijas: como imagen o como texto sin formato; en Mac es una de esas raras combinaciones que piden Ctrl junto a Cmd.", "Cola no formato que você escolher: como imagem ou como texto sem formatação; no Mac é uma das raras combinações que pedem Ctrl junto com Cmd.", "貼り方を選んで貼り付けます — 画像として、あるいは書式なしの文字として。Mac は Cmd に加えて Ctrl も押す珍しい組み合わせです。", "Fügt in einer Form ein, die Sie wählen — als Bild oder als unformatierten Text; am Mac ist es eine der seltenen Kombinationen, die Ctrl neben Cmd verlangt.", "Colle sous la forme choisie — image ou texte sans mise en forme ; sur Mac, c’est l’un des rares raccourcis qui réclame Ctrl en plus de Cmd.", "चुने हुए रूप में चिपकाता है — चित्र के रूप में या बिना formatting वाले लेख के रूप में; Mac पर यह उन गिने-चुने संयोजनों में है जो Cmd के साथ Ctrl भी माँगते हैं।", "按你选的形式粘贴——贴成图片，或贴成没有格式的文字；Mac 上它是少见地要在 Cmd 之外再加 Ctrl 的组合。", "按你選的形式貼上——貼成圖片，或貼成沒有格式的文字；Mac 上它是少見地要在 Cmd 之外再加 Ctrl 的組合。"],

  /* ───────── Animation ───────── */
  'powerpoint-copy-animation': ["개체에 걸린 애니메이션을 집어 옵니다. 한 개체에 붙은 효과를 하나만이 아니라 통째로 가져오므로, 여러 효과를 겹쳐 둔 개체에서 집으면 그 묶음이 함께 옮겨집니다.", "Picks up the animation on an object; it takes the whole set of effects rather than one, so an object with several stacked effects hands over all of them.", "Toma la animación de un objeto; se lleva todo el conjunto de efectos y no solo uno, así que un objeto con varios efectos apilados los entrega todos.", "Captura a animação de um objeto; leva o conjunto inteiro de efeitos e não apenas um, então um objeto com vários efeitos empilhados entrega todos.", "図形に付いた動きを拾います。効果を一つだけでなくまとめて持って行くので、複数重ねた図形から拾うとその束ごと移ります。", "Nimmt die Animation eines Objekts auf; sie holt den ganzen Satz an Effekten, nicht nur einen, ein Objekt mit mehreren gestapelten Effekten gibt also alle weiter.", "Prélève l’animation d’un objet ; il emporte l’ensemble des effets et non un seul, donc un objet aux effets empilés les transmet tous.", "किसी वस्तु पर लगी animation उठा लेता है; एक ही प्रभाव नहीं, पूरा समूह उठता है, इसलिए कई प्रभाव लदी वस्तु से उठाने पर सब साथ जाते हैं।", "把某个对象上的动画取过来；取的是整套效果而不是其中一个，所以叠了好几个效果的对象会把它们全交出去。", "把某個物件上的動畫取過來；取的是整套效果而不是其中一個，所以疊了好幾個效果的物件會把它們全交出去。"],
  'powerpoint-paste-animation': ["집어 온 애니메이션을 지금 고른 개체에 입힙니다. 그 개체에 이미 있던 효과는 남지 않고 갈아 끼워지므로, 겹쳐 쓸 생각이라면 순서를 먼저 정해 둡니다.", "Applies the animation you picked up to the selected object; whatever effects it had are replaced rather than added to, so decide the order before you paste.", "Aplica la animación tomada al objeto seleccionado; los efectos que tuviera se sustituyen en vez de sumarse, así que decide el orden antes de pegar.", "Aplica a animação capturada ao objeto selecionado; os efeitos que ele tinha são substituídos e não somados, então decida a ordem antes de colar.", "拾った動きを今選んでいる図形に当てます。その図形にあった効果は足されるのではなく置き換わるので、重ねたいなら順番を先に決めます。", "Überträgt die aufgenommene Animation auf das markierte Objekt; vorhandene Effekte werden ersetzt, nicht ergänzt — die Reihenfolge also vorher festlegen.", "Applique l’animation prélevée à l’objet sélectionné ; les effets qu’il possédait sont remplacés et non ajoutés, décidez donc de l’ordre avant de coller.", "उठाई हुई animation चुनी हुई वस्तु पर लगाता है; उस पर पहले से मौजूद प्रभाव जुड़ते नहीं, बदल जाते हैं, इसलिए चिपकाने से पहले क्रम तय कर लें।", "把取来的动画贴到当前选中的对象上；它原有的效果是被替换而不是叠加，所以要先想好顺序。", "把取來的動畫貼到目前選取的物件上；它原有的效果是被取代而不是疊加，所以要先想好順序。"],
  'powerpoint-animations-tab': ["리본의 Animations 탭을 엽니다. Animation Pane 자체에는 붙은 조합이 없어 이 탭을 열고 그 단추를 눌러야 하고, 맥 Office에는 이런 Alt 글자 힌트가 아예 없습니다.", "Opens the Animations tab on the ribbon; the Animation Pane itself has no binding, so you open the tab and click the button, and Office for Mac has no Alt key tips at all.", "Abre la pestaña Animations de la cinta; el Animation Pane no tiene combinación propia, así que se abre la pestaña y se pulsa el botón, y Office for Mac no tiene estas sugerencias con Alt.", "Abre a guia Animations na faixa; o Animation Pane não tem combinação própria, então você abre a guia e clica no botão, e o Office for Mac não tem essas dicas com Alt.", "リボンの Animations タブを開きます。Animation Pane 自体には割り当てが無いのでタブを開いてボタンを押すことになり、Mac の Office にはこの Alt のヒントがありません。", "Öffnet die Registerkarte Animations im Menüband; der Animation Pane selbst hat kein Kürzel, man öffnet also die Registerkarte und klickt die Schaltfläche — Office for Mac kennt diese Alt-Hinweise nicht.", "Ouvre l’onglet Animations du ruban ; l’Animation Pane n’a pas de raccourci propre, on ouvre donc l’onglet puis on clique le bouton, et Office for Mac n’a pas ces info-bulles avec Alt.", "ribbon का Animations टैब खोलता है; Animation Pane का अपना कोई संयोजन नहीं है, इसलिए टैब खोलकर बटन दबाना पड़ता है, और Office for Mac में Alt वाले ये संकेत ही नहीं हैं।", "打开功能区的 Animations 选项卡；Animation Pane 本身没有组合键，只能开这个选项卡再点那个按钮，而 Mac 版 Office 根本没有这套 Alt 提示。", "開啟功能區的 Animations 索引標籤；Animation Pane 本身沒有組合鍵，只能開這個索引標籤再按那個按鈕，而 Mac 版 Office 根本沒有這套 Alt 提示。"],

  /* ───────── Insert ───────── */
  'powerpoint-text-box': ["빈 자리에 글 상자를 그려 넣습니다. 함께 누르는 것이 아니라 차례로 누르는 리본 힌트이고, 맥 Office에는 이 힌트가 없어서 대신 Insert 메뉴로 갑니다.", "Draws a text box anywhere on the slide; the keys are pressed in sequence, not together, and Office for Mac has no key tips, so there you use the Insert menu.", "Dibuja un cuadro de texto en cualquier parte; las teclas se pulsan en orden y no juntas, y Office for Mac no tiene estas sugerencias, así que allí se usa el menú Insert.", "Desenha uma caixa de texto em qualquer ponto do slide; as teclas são pressionadas em sequência, não juntas, e o Office for Mac não tem dicas de tecla, então lá se usa o menu Insert.", "枚の好きな場所に文字の箱を描き入れます。同時押しではなく順に押すリボンのヒントで、Mac の Office にはこのヒントが無いため Insert のメニューを使います。", "Zeichnet ein Textfeld an eine beliebige Stelle; die Tasten kommen nacheinander, nicht gleichzeitig, und Office for Mac hat keine Zugriffstasten — dort nimmt man das Menü Insert.", "Dessine une zone de texte n’importe où ; les touches se pressent l’une après l’autre, pas ensemble, et Office for Mac n’a pas d’info-bulles de touches, on passe donc par le menu Insert.", "slide पर कहीं भी text box खींच देता है; कुंजियाँ साथ नहीं, क्रम से दबती हैं, और Office for Mac में ये संकेत नहीं हैं, वहाँ Insert मेनू से जाते हैं।", "在幻灯片上任意位置画一个文本框；这几个键是依次按而不是一起按，Mac 版 Office 没有这类提示，那边走 Insert 菜单。", "在投影片上任意位置畫一個文字方塊；這幾個鍵是依序按而不是一起按，Mac 版 Office 沒有這類提示，那邊走 Insert 選單。"],
  'powerpoint-shape': ["도형 갤러리를 열어 사각형이나 화살표를 골라 그립니다. 마지막 글자까지 눌러야 갤러리가 열리고, 도형은 방향키로도 고를 수 있습니다.", "Opens the shape gallery so you can draw a rectangle or an arrow; the gallery appears only after the last letter of the sequence, and the arrow keys can pick the shape too.", "Abre la galería de formas para dibujar un rectángulo o una flecha; la galería aparece solo tras la última letra de la secuencia, y las flechas también sirven para elegir.", "Abre a galeria de formas para você desenhar um retângulo ou uma seta; a galeria só aparece após a última letra da sequência, e as setas também escolhem a forma.", "図形のギャラリーを開き、四角や矢印を選んで描きます。並びの最後の文字を押して初めて開き、図形は方向キーでも選べます。", "Öffnet die Formengalerie für Rechteck oder Pfeil; sie erscheint erst nach dem letzten Buchstaben der Folge, und auch die Pfeiltasten wählen die Form.", "Ouvre la galerie de formes pour tracer un rectangle ou une flèche ; elle n’apparaît qu’après la dernière lettre de la séquence, et les flèches permettent aussi de choisir.", "आकृतियों की gallery खोलता है ताकि आयत या तीर खींचा जा सके; gallery क्रम के अंतिम अक्षर के बाद ही खुलती है, और आकृति तीर कुंजियों से भी चुनी जा सकती है।", "打开形状库，好画矩形或箭头；要按到这串键的最后一个字母它才出现，形状也可以用方向键挑。", "開啟形狀庫，好畫矩形或箭頭；要按到這串鍵的最後一個字母它才出現，形狀也可以用方向鍵挑。"],
  'powerpoint-picture': ["이 기계에 있는 그림 파일을 골라 넣습니다. 같은 자리에 온라인 그림과 스톡 이미지가 나란히 있어서, 마지막 글자를 잘못 누르면 다른 창이 열립니다.", "Inserts a picture file from this device; online pictures and stock images sit beside it in the same menu, so the wrong last letter opens the wrong browser.", "Inserta un archivo de imagen de este equipo; las imágenes en línea y las de archivo están al lado en el mismo menú, así que una última letra equivocada abre otra ventana.", "Insere um arquivo de imagem deste dispositivo; imagens online e do acervo ficam ao lado no mesmo menu, então errar a última letra abre a janela errada.", "この機械にある画像ファイルを選んで入れます。同じ場所にオンライン画像やストック画像が並ぶので、最後の文字を間違えると別の窓が開きます。", "Fügt eine Bilddatei von diesem Gerät ein; Onlinebilder und Stockbilder stehen im gleichen Menü daneben, ein falscher letzter Buchstabe öffnet also das falsche Fenster.", "Insère un fichier image depuis cet appareil ; les images en ligne et les images d’archive voisinent dans le même menu, une dernière lettre erronée ouvre donc la mauvaise fenêtre.", "इस उपकरण की चित्र फ़ाइल चुनकर डालता है; उसी मेनू में online चित्र और stock चित्र बग़ल में हैं, इसलिए अंतिम अक्षर ग़लत हुआ तो दूसरी खिड़की खुल जाती है।", "插入本机上的图片文件；同一个菜单里旁边就是联机图片和图库图片，最后一个字母按错就开错窗口。", "插入本機上的圖片檔案；同一個選單裡旁邊就是線上圖片和圖庫圖片，最後一個字母按錯就開錯視窗。"],
  'powerpoint-clipboard-pane': ["최근에 복사한 것들을 늘어놓는 Clipboard 창을 엽니다. 붙여넣기는 마지막 것만 주는데, 이 창은 앞서 복사한 것도 골라 붙일 수 있게 해 줍니다.", "Opens the Clipboard pane listing what you copied recently; ordinary pasting only gives you the last item, while this pane lets you pick an earlier one.", "Abre el panel Clipboard con lo copiado hace poco; pegar normal solo da el último elemento, mientras este panel deja elegir uno anterior.", "Abre o painel Clipboard com o que você copiou recentemente; colar normal só dá o último item, enquanto este painel deixa escolher um anterior.", "最近コピーしたものを並べる Clipboard の窓を開きます。普通の貼り付けは最後の一つだけですが、この窓なら前にコピーしたものも選んで貼れます。", "Öffnet den Clipboard-Bereich mit dem, was Sie zuletzt kopiert haben; normales Einfügen liefert nur das letzte Element, hier wählen Sie auch ein früheres.", "Ouvre le volet Clipboard avec vos copies récentes ; le collage ordinaire ne rend que le dernier élément, ce volet permet d’en choisir un plus ancien.", "हाल में copy की गई चीज़ें दिखाने वाला Clipboard pane खोलता है; सामान्य paste केवल आख़िरी चीज़ देता है, यह pane पहले वाली भी चुनने देता है।", "打开列出最近复制内容的 Clipboard 窗格；普通粘贴只给最后一次的内容，这个窗格能挑更早的一条。", "開啟列出最近複製內容的 Clipboard 窗格；普通貼上只給最後一次的內容，這個窗格能挑更早的一條。"],

  /* ───────── View ───────── */
  'powerpoint-notes-pane': ["장 아래의 메모 칸을 열고 닫습니다. 여기 적은 글이 발표자 화면에 나오는 그 메모이고, 청중 화면에는 나오지 않습니다.", "Shows or hides the notes box under the slide; what you type there is exactly what presenter view shows you, and the audience never sees it.", "Muestra u oculta el cuadro de notas bajo la diapositiva; lo que escribas ahí es lo que ve la vista del presentador, y el público nunca lo ve.", "Mostra ou esconde a caixa de anotações abaixo do slide; o que você escreve ali é o que a exibição do apresentador mostra, e a plateia nunca vê.", "枚の下のメモ欄を開いたり閉じたりします。ここに書いた文字が発表者用画面に出るメモで、客席の画面には出ません。", "Zeigt oder verbirgt das Notizenfeld unter der Folie; was dort steht, sieht genau die Referentenansicht — das Publikum nie.", "Affiche ou masque la zone de notes sous la diapositive ; ce qu’on y tape est exactement ce que montre le mode présentateur, jamais le public.", "slide के नीचे के notes बक्से को खोलता-बंद करता है; वहाँ लिखा वही है जो presenter view दिखाता है, दर्शकों को कभी नहीं।", "开关幻灯片下方的备注框；写在那里的字正是演讲者视图给你看的备注，观众看不到。", "開關投影片下方的備忘稿框；寫在那裡的字正是簡報者檢視給你看的備忘稿，觀眾看不到。"],
  'powerpoint-guides': ["맞춤을 돕는 안내선을 켜고 끕니다. 맥에서는 수식 키를 셋이나 함께 쥐어야 하고, 이 선은 인쇄에도 발표 화면에도 나오지 않습니다.", "Turns the alignment guides on and off; the Mac wants three modifiers at once, and the lines appear neither in print nor in the show.", "Activa y desactiva las guías de alineación; en Mac hay que sujetar tres modificadores a la vez, y las líneas no salen ni al imprimir ni en la presentación.", "Liga e desliga as guias de alinhamento; no Mac são três modificadores ao mesmo tempo, e as linhas não aparecem na impressão nem na apresentação.", "位置合わせの補助線を出したり消したりします。Mac では修飾キーを三つ同時に押す必要があり、この線は印刷にも本番の画面にも出ません。", "Schaltet die Ausrichtungslinien ein und aus; der Mac verlangt drei Modifikatoren gleichzeitig, und die Linien erscheinen weder im Druck noch in der Vorführung.", "Active et désactive les repères d’alignement ; le Mac réclame trois modificateurs à la fois, et ces lignes n’apparaissent ni à l’impression ni pendant le diaporama.", "संरेखण की सहायक रेखाएँ चालू-बंद करता है; Mac पर तीन modifier एक साथ पकड़ने पड़ते हैं, और ये रेखाएँ न छपती हैं न प्रस्तुति में दिखती हैं।", "开关用来对齐的参考线；Mac 上要同时按住三个修饰键，这些线既不打印也不出现在放映画面里。", "開關用來對齊的輔助線；Mac 上要同時按住三個修飾鍵，這些線既不列印也不出現在放映畫面裡。"],
  'powerpoint-gridlines': ["바탕에 격자를 켜고 끕니다. 두 운영체제가 같은 키를 쓰는 드문 자리이고, 개체가 격자에 달라붙게 하는 것은 따로 있는 설정입니다.", "Turns the background grid on and off; unusually both systems use the same key, and making objects snap to that grid is a separate setting.", "Activa y desactiva la cuadrícula de fondo; curiosamente ambos sistemas usan la misma tecla, y que los objetos se ajusten a ella es otro ajuste.", "Liga e desliga a grade de fundo; curiosamente os dois sistemas usam a mesma tecla, e fazer os objetos aderirem a ela é outra configuração.", "背景の格子を出したり消したりします。二つの OS が同じキーを使う珍しい場所で、図形を格子に吸い付かせるかどうかは別の設定です。", "Schaltet das Hintergrundraster ein und aus; ungewöhnlich nutzen beide Systeme dieselbe Taste, und das Einrasten am Raster ist eine eigene Einstellung.", "Active et désactive la grille de fond ; fait rare, les deux systèmes utilisent la même touche, et l’aimantation des objets sur la grille est un réglage distinct.", "पृष्ठभूमि की जाली चालू-बंद करता है; दोनों सिस्टम एक ही कुंजी इस्तेमाल करते हैं जो दुर्लभ है, और वस्तुओं को जाली से चिपकाना अलग सेटिंग है।", "开关背景网格；少见地，两个系统用的是同一个键，而让对象吸附到网格是另一项设置。", "開關背景格線；少見地，兩個系統用的是同一個鍵，而讓物件貼齊格線是另一項設定。"],
  'powerpoint-zoom-in': ["편집 화면을 확대합니다. 발표 화면은 그대로여서 청중이 보는 크기와는 상관이 없고, 작은 글자를 다듬을 때만 쓰는 값입니다.", "Zooms the editing view in; the show itself is untouched, so this changes nothing the audience sees and only helps you nudge small type.", "Amplía la vista de edición; la presentación no cambia, así que no altera nada de lo que ve el público y solo sirve para retocar letra pequeña.", "Amplia a visão de edição; a apresentação em si não muda, então nada do que a plateia vê é afetado e só ajuda a ajustar letras pequenas.", "編集画面を拡大します。本番の画面は変わらないので客席の見え方には関係なく、小さな文字を整えるときだけの値です。", "Vergrößert die Bearbeitungsansicht; die Vorführung bleibt unberührt, für das Publikum ändert sich nichts — es hilft nur beim Feinjustieren kleiner Schrift.", "Agrandit la vue d’édition ; le diaporama n’est pas touché, cela ne change rien pour le public et sert seulement à ajuster de petits caractères.", "संपादन दृश्य को बड़ा करता है; प्रस्तुति वैसी ही रहती है, इसलिए दर्शकों को दिखने वाले आकार से इसका कोई नाता नहीं, यह छोटे अक्षर सुधारने के काम आता है।", "放大编辑视图；放映本身不受影响，观众看到的大小一点没变，它只是方便你调小字。", "放大編輯檢視；放映本身不受影響，觀眾看到的大小一點沒變，它只是方便你調小字。"],
  'powerpoint-zoom-out': ["편집 화면을 축소합니다. 여러 장 보기에서는 축소판 크기가 줄어들어 한 화면에 더 많은 장이 들어옵니다.", "Zooms the editing view out; in slide sorter it shrinks the thumbnails instead, fitting more slides on the screen at once.", "Reduce la vista de edición; en el clasificador encoge las miniaturas y caben más diapositivas a la vez.", "Reduz a visão de edição; no classificador ele encolhe as miniaturas e cabem mais slides de uma vez.", "編集画面を縮小します。一覧では代わりにサムネイルが小さくなり、一画面に入る枚数が増えます。", "Verkleinert die Bearbeitungsansicht; in der Foliensortierung schrumpfen stattdessen die Miniaturen, sodass mehr Folien auf den Schirm passen.", "Réduit la vue d’édition ; dans la trieuse, ce sont les miniatures qui rétrécissent et plus de diapositives tiennent à l’écran.", "संपादन दृश्य को छोटा करता है; slide sorter में यह thumbnails छोटी कर देता है, जिससे एक परदे पर ज़्यादा slides आ जाती हैं।", "缩小编辑视图；在幻灯片浏览里它是把缩略图变小，一屏能装下更多张。", "縮小編輯檢視；在投影片瀏覽裡它是把縮圖變小，一個畫面能裝下更多張。"],
  'powerpoint-zoom-to-fit': ["장 하나가 창에 딱 맞도록 배율을 되돌립니다. 확대해 들어갔다가 지금 어디를 보고 있는지 잃었을 때 누르는 것입니다.", "Puts the zoom back so one whole slide fits the window — the key to press when you zoomed in and lost track of where you were.", "Devuelve el zoom para que una diapositiva entera quepa en la ventana: la tecla que se pulsa cuando te acercaste y perdiste la referencia.", "Devolve o zoom para que um slide inteiro caiba na janela: a tecla para apertar quando você ampliou e se perdeu.", "枚一つが窓にちょうど収まる倍率へ戻します。拡大して今どこを見ているか分からなくなったときに押すものです。", "Stellt den Zoom so zurück, dass eine ganze Folie ins Fenster passt — die Taste, wenn man sich beim Hineinzoomen verloren hat.", "Ramène le zoom pour qu’une diapositive entière tienne dans la fenêtre : la touche à presser quand on s’est perdu en zoomant.", "ज़ूम को वहाँ लौटाता है जहाँ पूरी slide खिड़की में समा जाए — बड़ा करते-करते जगह भूल जाएँ तो यही दबाते हैं।", "把缩放调回到一整张幻灯片刚好填满窗口——放大之后找不着位置时就按它。", "把縮放調回到一整張投影片剛好填滿視窗——放大之後找不著位置時就按它。"],
};
